    fn type_all_ports(t: &TypeStore) -> Vec<PortFullDto> {
        let mut out = Vec::new();
        for fw in &t.families {
            let Some(f) = fw.upgrade() else { continue };
            let Ok(fr) = f.read() else { continue };
            for p in &fr.ports {
                if let Ok(pr) = p.read() {
                    out.push(pr.to_full_dto());
                }
            }
        }
        out
    }


