pub mod kit_checkpoint {
    //! Checkpoints and materialized kit snapshots on the main / shared tree.
    use serde::{Deserialize, Serialize};
    use std::collections::HashMap;

    use crate::id::Id;
    use crate::kit_change::KitChange;
    use crate::kit_graph::{KitFullDto, KitGraph, KitGraphRef};

    #[derive(Clone, Debug, Serialize, Deserialize)]
    pub struct MaterializedKit {
        pub initial: KitFullDto,
        pub change_list: Vec<KitChange>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub computed: Option<KitFullDto>,
    }

    impl MaterializedKit {
        pub fn compute(&self) -> KitFullDto {
            let k = KitGraph::from_full_dto(self.initial.clone());
            for c in &self.change_list {
                let _ = KitChange::apply_forward(c, &k);
            }
            let out = k.read().expect("kit read").to_full_dto();
            out
        }
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    pub struct KitCheckpoint {
        pub id: Id,
        pub parent: Option<Id>,
        pub changes: Vec<KitChange>,
        pub message: Option<String>,
        pub time: Option<String>,
        pub authors: Vec<Id>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub release: Option<MaterializedKit>,
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub enum KitCheckpointCommand {
        ReadKitCommands { commands: Vec<crate::read::ReadKitCommand> },
        MarkAsRelease,
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub enum KitCheckpointCommandResult {
        ReadKitCommands { results: Vec<crate::read::ReadKitCommandOutput> },
        MarkAsRelease { ok: bool },
        Nothing,
    }

    impl KitCheckpoint {
        pub fn new(parent: Option<Id>, changes: Vec<KitChange>, message: Option<String>) -> Self {
            let id = Self::compute_id(parent.as_ref(), &changes);
            Self { id, parent, changes, message, time: None, authors: Vec::new(), release: None }
        }

        pub fn compute_id(parent: Option<&Id>, changes: &[KitChange]) -> Id {
            let payload = serde_json::json!({
                "parent": parent.map(|p| p.as_str()),
                "changes": changes,
            });
            let s = serde_json::to_string(&payload).unwrap_or_default();
            crate::id::Id::from_blake3_canonical(&s)
        }

        pub fn chain_root_to_leaf(&self, map: &HashMap<Id, KitCheckpoint>) -> Vec<Id> {
            Self::chain_root_to_leaf_from(&self.id, map)
        }

        pub fn chain_root_to_leaf_from(at: &Id, map: &HashMap<Id, KitCheckpoint>) -> Vec<Id> {
            let mut out = vec![at.clone()];
            let mut cur = at.clone();
            loop {
                let parent = map.get(&cur).and_then(|c| c.parent.as_ref().cloned());
                match parent {
                    None => break,
                    Some(p) if out.contains(&p) => break,
                    Some(p) => {
                        out.push(p.clone());
                        cur = p;
                    }
                }
            }
            out.reverse();
            out
        }

        pub fn rebuild_children_map(checkpoints: &HashMap<Id, KitCheckpoint>) -> HashMap<Option<Id>, Vec<Id>> {
            let mut children: HashMap<Option<Id>, Vec<Id>> = HashMap::new();
            for (cid, cp) in checkpoints {
                children.entry(cp.parent.clone()).or_default().push(cid.clone());
            }
            for v in children.values_mut() {
                v.sort_by(|a, b| a.as_str().cmp(b.as_str()));
            }
            children
        }

        pub fn materialize(initial: &KitFullDto, map: &HashMap<Id, KitCheckpoint>, at: Option<&Id>) -> KitFullDto {
            let Some(at_id) = at else {
                return initial.clone();
            };
            let path = Self::chain_root_to_leaf_from(at_id, map);
            let k = KitGraph::from_full_dto(initial.clone());
            for cid in &path {
                if let Some(cp) = map.get(cid) {
                    for ch in &cp.changes {
                        let _ = KitChange::apply_forward(ch, &k);
                    }
                }
            }
            let out = k.read().expect("kit read").to_full_dto();
            out
        }

        pub fn materialize_graph(initial: &KitFullDto, map: &HashMap<Id, KitCheckpoint>, at: Option<&Id>) -> KitGraphRef {
            let Some(at_id) = at else {
                return KitGraph::from_full_dto(initial.clone());
            };
            let path = Self::chain_root_to_leaf_from(at_id, map);
            let k = KitGraph::from_full_dto(initial.clone());
            for cid in &path {
                if let Some(cp) = map.get(cid) {
                    for ch in &cp.changes {
                        let _ = KitChange::apply_forward(ch, &k);
                    }
                }
            }
            k
        }

        pub fn mark_as_release(&mut self, initial: KitFullDto, all_checkpoints: &HashMap<Id, KitCheckpoint>) {
            let path = Self::chain_root_to_leaf_from(&self.id, all_checkpoints);
            let mut change_list: Vec<KitChange> = Vec::new();
            for id in &path {
                if let Some(c) = all_checkpoints.get(id) {
                    change_list.extend(c.changes.iter().cloned());
                }
            }
            let computed = Some(Self::materialize(&initial, all_checkpoints, Some(&self.id)));
            self.release = Some(MaterializedKit { initial, change_list, computed });
        }
    }
}
pub mod kit_alternative {
    //! Named ordered list of checkpoints branching from the main kit line.
    use serde::{Deserialize, Serialize};

    use crate::id::Id;

    #[derive(Clone, Debug, Serialize, Deserialize)]
    pub struct KitAlternative {
        pub id: Id,
        pub name: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub root: Option<Id>,
        pub checkpoints: Vec<Id>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub draft: Option<crate::kit_draft::Draft>,
    }

    impl KitAlternative {
        pub fn new(name: String, from_checkpoint: Option<Id>) -> Self {
            let id = Id::new_v7();
            match from_checkpoint {
                Some(cp) => Self { id, name, root: Some(cp.clone()), checkpoints: vec![cp], draft: None },
                None => Self { id, name, root: None, checkpoints: vec![], draft: None },
            }
        }

        pub fn tip(&self) -> Option<&Id> {
            self.checkpoints.last()
        }

        pub fn append(&mut self, cp: Id) {
            self.checkpoints.push(cp);
        }

        pub fn collapse_to(&mut self, new_tip: Id) {
            let anchor = self.root.clone().or_else(|| self.checkpoints.first().cloned()).expect("alt collapse");
            self.root = Some(anchor.clone());
            self.checkpoints = vec![anchor, new_tip];
        }
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub enum KitAlternativeCommand {
        ReadKitCommands { commands: Vec<crate::read::ReadKitCommand> },
        UnifyKitCheckpointsToSingleKitCheckpoint { message: String },
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub enum KitAlternativeCommandResult {
        ReadKitCommands {
            results: Vec<crate::read::ReadKitCommandOutput>,
        },
        UnifyKitCheckpointsToSingleKitCheckpoint {
            #[serde(rename = "newCheckpointId")]
            new_checkpoint_id: Id,
        },
        Nothing,
    }
}
pub mod kit_transaction {
    //! One transaction: a stack of [`crate::kit_change::KitChange`] with undo/redo.
    use serde::{Deserialize, Serialize};

    use crate::id::Id;
    use crate::kit_change::KitChange;
    use crate::read::{ReadKitCommand, ReadKitCommandOutput};

    #[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq, async_graphql::Enum, Copy)]
    #[serde(rename_all = "camelCase")]
    #[graphql(rename_items = "camelCase")]
    pub enum TransactionState {
        Open,
        Finalized,
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    pub struct Transaction {
        pub id: Id,
        pub changes: Vec<KitChange>,
        pub redo_changes: Vec<KitChange>,
        pub state: TransactionState,
    }

    impl Transaction {
        pub fn new(id: Id) -> Self {
            Self { id, changes: Vec::new(), redo_changes: Vec::new(), state: TransactionState::Open }
        }

        pub fn is_open(&self) -> bool {
            matches!(self.state, TransactionState::Open)
        }

        pub fn record(&mut self, change: KitChange) {
            self.changes.push(change);
            self.redo_changes.clear();
        }

        pub fn undo_last(&mut self) -> Option<KitChange> {
            let ch = self.changes.pop()?;
            self.redo_changes.push(ch.clone());
            Some(ch)
        }

        pub fn redo_last(&mut self) -> Option<KitChange> {
            let ch = self.redo_changes.pop()?;
            self.changes.push(ch.clone());
            Some(ch)
        }

        pub fn mark_finalized(&mut self) {
            self.state = TransactionState::Finalized;
        }
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub enum TransactionCommand {
        ReadKitCommands { commands: Vec<ReadKitCommand> },
        ChangeKitCommands { commands: Vec<crate::change_command::ChangeKitCommand> },
        Finalize,
        Abort,
        Undo,
        UndoAll,
        CanUndo,
        Redo,
        RedoAll,
        CanRedo,
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub enum TransactionCommandResult {
        ReadKitCommands { results: Vec<ReadKitCommandOutput> },
        ChangeKitCommands { count: usize },
        Finalize { ok: bool },
        Abort { ok: bool },
        Undo { ok: bool },
        UndoAll { ok: bool },
        CanUndo { can: bool },
        Redo { ok: bool },
        RedoAll { ok: bool },
        CanRedo { can: bool },
        Nothing,
    }

    impl Transaction {
        pub fn can_undo(&self) -> bool {
            !self.changes.is_empty()
        }

        pub fn can_redo(&self) -> bool {
            !self.redo_changes.is_empty()
        }
    }
}
pub mod kit_draft {
    //! Draft: stack of finalized transactions on top of a checkpoint tip, plus optional open transaction.
    use serde::{Deserialize, Serialize};

    use crate::id::Id;
    use crate::kit_change::KitChange;
    use crate::kit_graph::KitFullDto;
    use crate::kit_graph::KitGraph;
    use crate::kit_graph::KitGraphRef;
    use crate::kit_transaction::{Transaction, TransactionCommand, TransactionCommandResult};
    use crate::read::{ReadKitCommand, ReadKitCommandOutput};

    #[derive(Clone, Debug, Serialize, Deserialize)]
    pub struct Draft {
        pub id: Id,
        pub parent_checkpoint: Option<Id>,
        pub target_alternative: Option<Id>,
        pub before: KitFullDto,
        pub transactions: Vec<Transaction>,
        pub redo_transactions: Vec<Transaction>,
        pub open_transaction: Option<Transaction>,
    }

    impl Draft {
        pub fn new(parent_checkpoint: Option<Id>, target_alternative: Option<Id>, before: KitFullDto) -> Self {
            Self { id: Id::new_v7(), parent_checkpoint, target_alternative, before, transactions: Vec::new(), redo_transactions: Vec::new(), open_transaction: None }
        }

        pub fn open_tx_id(&self) -> Option<&Id> {
            self.open_transaction.as_ref().map(|t| &t.id)
        }

        pub fn has_open_transaction(&self) -> bool {
            self.open_transaction.is_some()
        }

        pub fn start_transaction(&mut self) -> crate::error::Result<Id> {
            if self.open_transaction.is_some() {
                return Err(crate::error::SemioError::InvalidOperation("transaction already open".into()));
            }
            let tid = Id::new_v7();
            self.open_transaction = Some(Transaction::new(tid.clone()));
            Ok(tid)
        }

        pub fn open_transaction_mut(&mut self, txid: &Id) -> Option<&mut Transaction> {
            self.open_transaction.as_mut().filter(|t| t.id == *txid)
        }

        pub fn open_transaction_ref(&self, txid: &Id) -> Option<&Transaction> {
            self.open_transaction.as_ref().filter(|t| t.id == *txid)
        }

        pub fn finalize_transaction(&mut self, txid: &Id) -> crate::error::Result<()> {
            let mut tx = self.open_transaction.take().filter(|t| t.id == *txid).ok_or_else(|| crate::error::SemioError::InvalidOperation("no tx to finalize".into()))?;
            tx.mark_finalized();
            self.transactions.push(tx);
            Ok(())
        }

        pub fn take_open_transaction(&mut self, txid: &Id) -> crate::error::Result<Transaction> {
            self.open_transaction.take().filter(|t| t.id == *txid).ok_or_else(|| crate::error::SemioError::InvalidOperation("tx id mismatch".into()))
        }

        pub fn pop_finalized(&mut self) -> Option<Transaction> {
            self.transactions.pop()
        }

        pub fn push_redo_transaction(&mut self, tx: Transaction) {
            self.redo_transactions.push(tx);
        }

        pub fn pop_redo_transaction(&mut self) -> Option<Transaction> {
            self.redo_transactions.pop()
        }

        pub fn push_finalized(&mut self, tx: Transaction) {
            self.transactions.push(tx);
        }

        pub fn can_undo_draft(&self) -> bool {
            !self.transactions.is_empty()
        }

        pub fn can_redo_draft(&self) -> bool {
            !self.redo_transactions.is_empty()
        }

        pub fn materialize_working_graph(&self) -> crate::error::Result<KitGraphRef> {
            let k = KitGraph::from_full_dto(self.before.clone());
            for tx in &self.transactions {
                for ch in &tx.changes {
                    KitChange::apply_forward(ch, &k).map_err(|e| crate::error::SemioError::InvalidOperation(e.to_string()))?;
                }
            }
            if let Some(ot) = &self.open_transaction {
                for ch in &ot.changes {
                    KitChange::apply_forward(ch, &k).map_err(|e| crate::error::SemioError::InvalidOperation(e.to_string()))?;
                }
            }
            Ok(k)
        }
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub enum KitDraftCommand {
        ReadKitCommands {
            commands: Vec<ReadKitCommand>,
        },
        StartTransaction,
        FinalizeToKitCheckpoint {
            #[serde(rename = "message")]
            message: String,
        },
        Abort,
        Undo {
            count: i32,
        },
        CanUndo {
            count: i32,
        },
        Redo {
            count: i32,
        },
        CanRedo {
            count: i32,
        },
        ExecuteTransactionCommands {
            id: Id,
            commands: Vec<TransactionCommand>,
        },
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub enum KitDraftCommandResult {
        ReadKitCommands {
            results: Vec<ReadKitCommandOutput>,
        },
        StartTransaction {
            #[serde(rename = "transactionId")]
            transaction_id: Id,
        },
        FinalizeToKitCheckpoint {
            #[serde(rename = "checkpointId")]
            checkpoint_id: Id,
        },
        Abort {
            ok: bool,
        },
        Undo {
            ok: bool,
        },
        CanUndo {
            can: bool,
        },
        Redo {
            ok: bool,
        },
        CanRedo {
            can: bool,
        },
        ExecuteTransactionCommands {
            results: Vec<TransactionCommandResult>,
        },
        Nothing,
    }
}
pub mod kit_read_scope {
    use crate::error::{Result, SemioError};
    use crate::id::Id;
    use crate::kit_graph::KitGraphRef;
    use serde::{Deserialize, Serialize};

    #[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub enum KitReadScope {
        TheKit,
        Checkpoint {
            #[serde(rename = "checkpointId")]
            checkpoint_id: Id,
        },
        Alternative {
            #[serde(rename = "alternativeId")]
            alternative_id: Id,
        },
        Draft {
            /// `None` means the main kit line (`the_kit_draft`); `Some(alternativeId)` scopes to that alternative's single draft slot.
            #[serde(rename = "alternativeId", default, skip_serializing_if = "Option::is_none")]
            alternative_id: Option<Id>,
            #[serde(rename = "draftId")]
            draft_id: Id,
        },
        Transaction {
            #[serde(rename = "alternativeId", default, skip_serializing_if = "Option::is_none")]
            alternative_id: Option<Id>,
            #[serde(rename = "draftId")]
            draft_id: Id,
            #[serde(rename = "transactionId")]
            transaction_id: Id,
        },
    }

    use crate::kit_draft::Draft as KitDraft;

    fn materialize_draft_working_graph(kit: &KitGraphRef, alternative_id: Option<&Id>, draft_id: &Id) -> Result<KitGraphRef> {
        let d: KitDraft = {
            let g = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
            g.clone_draft_for_owner(alternative_id, draft_id).ok_or_else(|| SemioError::InvalidOperation("unknown draft for read scope".into()))?
        };
        d.materialize_working_graph()
    }

    fn materialize_transaction_read_graph(kit: &KitGraphRef, alternative_id: Option<&Id>, draft_id: &Id, transaction_id: &Id) -> Result<KitGraphRef> {
        {
            let g = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
            let d = g.draft_ref_for_owner(alternative_id, draft_id).ok_or_else(|| SemioError::InvalidOperation("unknown draft for transaction read scope".into()))?;
            let _ = d.open_transaction_ref(transaction_id).ok_or_else(|| SemioError::InvalidOperation("read scope: transaction is not the open transaction".into()))?;
        }
        materialize_draft_working_graph(kit, alternative_id, draft_id)
    }

    pub fn resolve_read_graph(kit: &KitGraphRef, scope: &KitReadScope) -> Result<KitGraphRef> {
        let g0 = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
        let view = match scope {
            KitReadScope::TheKit => {
                drop(g0);
                return Ok(kit.clone());
            }
            KitReadScope::Checkpoint { checkpoint_id } => g0.materialize_graph_at(Some(checkpoint_id)),
            KitReadScope::Alternative { alternative_id } => {
                let tip = g0.alternative_tip(alternative_id);
                let at = match tip.as_ref() {
                    Some(t) => Some(t),
                    None => g0.the_kit_head.as_ref(),
                };
                g0.materialize_graph_at(at)
            }
            KitReadScope::Draft { alternative_id, draft_id } => {
                drop(g0);
                return materialize_draft_working_graph(kit, alternative_id.as_ref(), draft_id);
            }
            KitReadScope::Transaction { alternative_id, draft_id, transaction_id } => {
                drop(g0);
                return materialize_transaction_read_graph(kit, alternative_id.as_ref(), draft_id, transaction_id);
            }
        };
        drop(g0);
        Ok(view)
    }
}

