#[cfg(not(target_arch = "wasm32"))]
pub mod kit_conflict_registry {
    use std::collections::HashMap;
    use std::sync::{Arc, Mutex};

    use crate::id::Id;

    pub use crate::kit_backbone_wire::{ConflictResolution, KitConflict};

    #[derive(Clone, Debug, Default)]
    pub struct ConflictRegistry {
        inner: Arc<Mutex<HashMap<Id, KitConflict>>>,
    }

    impl ConflictRegistry {
        pub fn new() -> Self {
            Self { inner: Arc::new(Mutex::new(HashMap::new())) }
        }

        pub fn insert(&self, c: KitConflict) {
            let mut g = self.inner.lock().expect("conflict registry lock");
            g.insert(c.id.clone(), c);
        }

        pub fn list(&self) -> Vec<KitConflict> {
            let g = self.inner.lock().expect("conflict registry lock");
            let mut v: Vec<KitConflict> = g.values().cloned().collect();
            v.sort_by(|a, b| a.id.as_str().cmp(b.id.as_str()));
            v
        }

        pub fn remove(&self, id: &Id) -> Option<KitConflict> {
            let mut g = self.inner.lock().expect("conflict registry lock");
            g.remove(id)
        }
    }
}

#[cfg(not(target_arch = "wasm32"))]
pub mod backbone {
    use std::collections::{HashMap, HashSet};
    use std::io::Write;
    use std::path::{Path, PathBuf};

    use serde::{Deserialize, Serialize};

    use crate::error::{Result, SemioError};
    use crate::id::Id;
    use crate::kit_alternative::KitAlternative;
    use crate::kit_checkpoint::KitCheckpoint;
    use crate::kit_graph::{KitFullDto, KitGraph, KitGraphRef};

    #[derive(Clone, Debug, Serialize, Deserialize)]
    pub struct BackboneSnapshot {
        pub initial: KitFullDto,
        pub checkpoints: HashMap<Id, KitCheckpoint>,
        pub the_kit_head: Option<Id>,
        pub alternatives: HashMap<Id, KitAlternative>,
        pub children: HashMap<Option<Id>, Vec<Id>>,
    }

    impl BackboneSnapshot {
        pub fn from_graph(g: &KitGraph) -> Self {
            Self { initial: g.initial.clone(), checkpoints: g.checkpoints.clone(), the_kit_head: g.the_kit_head.clone(), alternatives: g.alternatives.clone(), children: g.children.clone() }
        }

        pub fn verify_linear_mainline_extension(auth: &Self, proposed: &Self) -> std::result::Result<(), String> {
            if auth.initial != proposed.initial {
                return Err("initial kit mismatch".into());
            }
            for (id, cp) in &auth.checkpoints {
                match proposed.checkpoints.get(id) {
                    Some(p) => {
                        let pj = serde_json::to_value(p).map_err(|e| e.to_string())?;
                        let cj = serde_json::to_value(cp).map_err(|e| e.to_string())?;
                        if pj != cj {
                            return Err(format!("checkpoint {id} missing or diverged"));
                        }
                    }
                    _ => return Err(format!("checkpoint {id} missing or diverged")),
                }
            }
            let tip = proposed.the_kit_head.clone().ok_or_else(|| "proposed has no the_kit_head".to_string())?;
            let ncp = proposed.checkpoints.get(&tip).ok_or_else(|| "tip checkpoint missing".to_string())?;
            if ncp.parent != auth.the_kit_head {
                return Err(format!("checkpoint parent {:?} != backbone tip {:?}", ncp.parent, auth.the_kit_head));
            }
            let new_ids: HashSet<_> = proposed.checkpoints.keys().filter(|k| !auth.checkpoints.contains_key(*k)).cloned().collect();
            if new_ids.len() != 1 || !new_ids.contains(&tip) {
                return Err("expected exactly one new checkpoint on main line".into());
            }
            Ok(())
        }
    }

    pub fn apply_snap_to_graph(kit: &KitGraphRef, snap: &BackboneSnapshot) -> crate::error::SetResult {
        use crate::error::SetError;
        let dto = KitCheckpoint::materialize(&snap.initial, &snap.checkpoints, snap.the_kit_head.as_ref());
        KitGraph::replace_from_full_dto(kit, dto)?;
        let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
        g.initial = snap.initial.clone();
        g.checkpoints = snap.checkpoints.clone();
        g.the_kit_head = snap.the_kit_head.clone();
        g.alternatives = snap.alternatives.clone();
        g.children = snap.children.clone();
        g.clear_all_working_drafts();
        Ok(())
    }

    pub use crate::kit_backbone_wire::BackboneConfig;

    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub enum ProposeOutcome {
        Accepted,
        Rejected { current_tip: Option<Id> },
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub struct BackboneStatusDto {
        pub attached: bool,
        pub kind: Option<String>,
        pub backbone_tip: Option<Id>,
        pub pending_wip_checkpoints: usize,
    }

    pub trait BackboneDriver: Send {
        fn pull(&self) -> Result<BackboneSnapshot>;
        fn persist_full(&self, proposed: &BackboneSnapshot) -> Result<ProposeOutcome>;
        fn set_active_checkpoint(&self, _id: Option<&Id>) -> Result<()> {
            Ok(())
        }
    }

    pub struct DevBackbone {
        path: PathBuf,
    }

    impl DevBackbone {
        pub fn new(path: PathBuf) -> Self {
            Self { path }
        }

        fn read_file(&self) -> Result<BackboneSnapshot> {
            if !self.path.exists() {
                return Err(SemioError::InvalidOperation(format!("dev backbone file missing: {}", self.path.display())));
            }
            let s = std::fs::read_to_string(&self.path).map_err(|e| SemioError::Other(e.to_string()))?;
            let mut snap: BackboneSnapshot = serde_json::from_str(&s).map_err(|e| SemioError::Other(e.to_string()))?;
            if snap.children.is_empty() && !snap.checkpoints.is_empty() {
                snap.children = KitCheckpoint::rebuild_children_map(&snap.checkpoints);
            }
            Ok(snap)
        }

        fn write_atomic(&self, snap: &BackboneSnapshot) -> Result<()> {
            if let Some(parent) = self.path.parent() {
                if !parent.as_os_str().is_empty() {
                    std::fs::create_dir_all(parent).map_err(|e| SemioError::Other(e.to_string()))?;
                }
            }
            let dir = self.path.parent().unwrap_or_else(|| Path::new("."));
            let mut tmp = tempfile::NamedTempFile::new_in(dir).map_err(|e| SemioError::Other(e.to_string()))?;
            let json = serde_json::to_string_pretty(snap).map_err(|e| SemioError::Other(e.to_string()))?;
            std::io::Write::write_all(&mut tmp, json.as_bytes()).map_err(|e| SemioError::Other(e.to_string()))?;
            tmp.flush().map_err(|e| SemioError::Other(e.to_string()))?;
            tmp.persist(&self.path).map_err(|e| SemioError::Other(e.error.to_string()))?;
            Ok(())
        }
    }

    impl BackboneDriver for DevBackbone {
        fn pull(&self) -> Result<BackboneSnapshot> {
            self.read_file()
        }

        fn persist_full(&self, proposed: &BackboneSnapshot) -> Result<ProposeOutcome> {
            let auth = if self.path.exists() { self.read_file()? } else { BackboneSnapshot { initial: proposed.initial.clone(), checkpoints: HashMap::new(), the_kit_head: None, alternatives: HashMap::new(), children: HashMap::new() } };
            if BackboneSnapshot::verify_linear_mainline_extension(&auth, proposed).is_err() {
                return Ok(ProposeOutcome::Rejected { current_tip: auth.the_kit_head.clone() });
            }
            if self.path.exists() {
                let auth2 = self.read_file()?;
                if auth2.the_kit_head != auth.the_kit_head {
                    return Ok(ProposeOutcome::Rejected { current_tip: auth2.the_kit_head.clone() });
                }
            }
            self.write_atomic(proposed)?;
            Ok(ProposeOutcome::Accepted)
        }
    }

    pub struct LocalBackbone {
        folder: PathBuf,
    }

    impl LocalBackbone {
        pub fn new(folder: PathBuf) -> Self {
            Self { folder }
        }
    }

    impl BackboneDriver for LocalBackbone {
        fn pull(&self) -> Result<BackboneSnapshot> {
            let k = KitGraph::load_local_folder(&self.folder)?;
            let g = k.read().map_err(|_| SemioError::LockPoisoned("kit".into()))?;
            Ok(BackboneSnapshot::from_graph(&g))
        }

        fn persist_full(&self, proposed: &BackboneSnapshot) -> Result<ProposeOutcome> {
            let auth = if self.folder.join(".semio").join("kit.db").exists() {
                self.pull()?
            } else {
                BackboneSnapshot { initial: proposed.initial.clone(), checkpoints: HashMap::new(), the_kit_head: None, alternatives: HashMap::new(), children: HashMap::new() }
            };
            if BackboneSnapshot::verify_linear_mainline_extension(&auth, proposed).is_err() {
                return Ok(ProposeOutcome::Rejected { current_tip: auth.the_kit_head.clone() });
            }
            let dto = KitCheckpoint::materialize(&proposed.initial, &proposed.checkpoints, proposed.the_kit_head.as_ref());
            let k = KitGraph::from_full_dto(dto);
            {
                let mut g = k.write().map_err(|_| SemioError::LockPoisoned("kit".into()))?;
                g.initial = proposed.initial.clone();
                g.checkpoints = proposed.checkpoints.clone();
                g.the_kit_head = proposed.the_kit_head.clone();
                g.alternatives = proposed.alternatives.clone();
                g.children = proposed.children.clone();
            }
            k.read().map_err(|_| SemioError::LockPoisoned("kit".into()))?.save_local_folder(&self.folder)?;
            Ok(ProposeOutcome::Accepted)
        }

        fn set_active_checkpoint(&self, id: Option<&Id>) -> Result<()> {
            let k = KitGraph::load_local_folder(&self.folder)?;
            let dto = {
                let g = k.read().map_err(|_| SemioError::LockPoisoned("kit".into()))?;
                KitCheckpoint::materialize(&g.initial, &g.checkpoints, id)
            };
            let k2 = KitGraph::from_full_dto(dto);
            k2.read().map_err(|_| SemioError::LockPoisoned("kit".into()))?.save_local_folder(&self.folder)?;
            Ok(())
        }
    }

    pub struct RemoteBackbone {
        hub_url: String,
        session_id: String,
    }

    impl RemoteBackbone {
        pub fn new(hub_url: String, session_id: String) -> Self {
            Self { hub_url, session_id }
        }
    }

    impl BackboneDriver for RemoteBackbone {
        fn pull(&self) -> Result<BackboneSnapshot> {
            let k = KitGraph::load_remote_session(&self.hub_url, &self.session_id)?;
            let g = k.read().map_err(|_| SemioError::LockPoisoned("kit".into()))?;
            Ok(BackboneSnapshot::from_graph(&g))
        }

        fn persist_full(&self, _proposed: &BackboneSnapshot) -> Result<ProposeOutcome> {
            Err(SemioError::InvalidOperation("Remote backbone commit requires an authenticated RemoteKitSession (owner token). Use Dev or Local backbone.".into()))
        }
    }

    pub enum BackboneKind {
        Memory(MemoryBackbone),
        Dev(DevBackbone),
        Local(LocalBackbone),
        Remote(RemoteBackbone),
    }

    #[derive(Clone, Debug, Default)]
    pub struct MemoryBackbone;

    impl BackboneDriver for MemoryBackbone {
        fn pull(&self) -> Result<BackboneSnapshot> {
            Err(SemioError::InvalidOperation("memory backbone has no snapshot source".into()))
        }

        fn persist_full(&self, _proposed: &BackboneSnapshot) -> Result<ProposeOutcome> {
            Ok(ProposeOutcome::Accepted)
        }
    }

    impl BackboneKind {
        pub fn from_config(cfg: &BackboneConfig) -> Result<Self> {
            match cfg {
                BackboneConfig::Memory => Ok(Self::Memory(MemoryBackbone)),
                BackboneConfig::Dev { path } => Ok(Self::Dev(DevBackbone::new(PathBuf::from(path)))),
                BackboneConfig::Local { folder } => Ok(Self::Local(LocalBackbone::new(PathBuf::from(folder)))),
                BackboneConfig::Remote { url, session_id } => Ok(Self::Remote(RemoteBackbone::new(url.clone(), session_id.clone()))),
            }
        }

        pub fn pull(&self) -> Result<BackboneSnapshot> {
            match self {
                Self::Memory(m) => m.pull(),
                Self::Dev(d) => d.pull(),
                Self::Local(l) => l.pull(),
                Self::Remote(r) => r.pull(),
            }
        }

        pub fn persist_full(&self, proposed: &BackboneSnapshot) -> Result<ProposeOutcome> {
            match self {
                Self::Memory(m) => m.persist_full(proposed),
                Self::Dev(d) => d.persist_full(proposed),
                Self::Local(l) => l.persist_full(proposed),
                Self::Remote(r) => r.persist_full(proposed),
            }
        }

        pub fn set_active_checkpoint(&self, id: Option<&Id>) -> Result<()> {
            match self {
                Self::Local(l) => l.set_active_checkpoint(id),
                _ => Ok(()),
            }
        }

        pub fn kind_name(&self) -> &'static str {
            match self {
                Self::Memory(_) => "memory",
                Self::Dev(_) => "dev",
                Self::Local(_) => "local",
                Self::Remote(_) => "remote",
            }
        }
    }
}

#[cfg(not(target_arch = "wasm32"))]
pub mod wip_kit {
    use std::sync::mpsc::{Receiver, Sender};

    use crate::backbone::BackboneSnapshot;
    use crate::kit_graph::KitGraphRef;
    use crate::kit_store_command::{KitStoreCommand, KitStoreCommandResult};

    pub enum WipMsg {
        Exec { cmd: KitStoreCommand, reply: Sender<crate::error::Result<KitStoreCommandResult>> },
        ApplyAuth { snap: BackboneSnapshot, reply: Sender<crate::error::SetResult> },
    }

    pub enum CoordMsg {
        WipProposal { proposed: BackboneSnapshot, reply: Option<Sender<crate::error::Result<()>>> },
        SyncNow,
        Attach { cfg: crate::kit_backbone_wire::BackboneConfig, reply: Sender<crate::error::Result<()>> },
        Detach { reply: Sender<()> },
        Status { reply: Sender<crate::backbone::BackboneStatusDto> },
        SetActiveCheckpoint { id: Option<crate::id::Id>, reply: Sender<crate::error::Result<()>> },
        ResolveConflict { id: crate::id::Id, strategy: crate::kit_conflict_registry::ConflictResolution, wip: KitGraphRef, reply: Sender<crate::error::Result<()>> },
    }

    fn scan_finalize(graph: &KitGraphRef, res: &KitStoreCommandResult, coord: &Sender<CoordMsg>) {
        use crate::kit_draft::KitDraftCommandResult;
        if let KitStoreCommandResult::ExecuteKitDraftCommands { results } = res {
            for dr in results {
                if let KitDraftCommandResult::FinalizeToKitCheckpoint { .. } = dr {
                    let proposed = {
                        let g = graph.read().expect("wip graph");
                        crate::backbone::BackboneSnapshot::from_graph(&g)
                    };
                    let _ = coord.send(CoordMsg::WipProposal { proposed, reply: None });
                }
            }
        }
    }

    pub fn run(graph: KitGraphRef, rx: Receiver<WipMsg>, coord: Sender<CoordMsg>) {
        while let Ok(msg) = rx.recv() {
            match msg {
                WipMsg::Exec { cmd, reply } => {
                    let r = cmd.execute(&graph);
                    if let Ok(ref ok) = r {
                        scan_finalize(&graph, ok, &coord);
                    }
                    let _ = reply.send(r);
                }
                WipMsg::ApplyAuth { snap, reply } => {
                    let r = crate::backbone::apply_snap_to_graph(&graph, &snap);
                    let _ = reply.send(r);
                }
            }
        }
    }
}

#[cfg(not(target_arch = "wasm32"))]
pub mod kit_coordinator {
    use std::sync::mpsc::Receiver;
    use std::sync::{Arc, Mutex};

    use chrono::Utc;

    use crate::backbone::{apply_snap_to_graph, BackboneKind, BackboneSnapshot, ProposeOutcome};
    use crate::error::{Result, SemioError};
    use crate::kit_change::KitChange;
    use crate::kit_checkpoint::KitCheckpoint;
    use crate::kit_conflict_registry::{ConflictRegistry, KitConflict};
    use crate::kit_graph::KitGraphRef;
    use crate::wip_kit::{CoordMsg, WipMsg};

    fn process_proposal(backbone: &BackboneKind, sync: &KitGraphRef, conflicts: &ConflictRegistry, proposed: &BackboneSnapshot, wip_tx: &std::sync::mpsc::Sender<WipMsg>) -> Result<()> {
        let auth = backbone.pull()?;
        apply_snap_to_graph(sync, &auth).map_err(|e| SemioError::InvalidOperation(e.to_string()))?;
        let tip = proposed.the_kit_head.clone().ok_or_else(|| SemioError::InvalidOperation("wip has no the_kit_head".into()))?;
        if auth.checkpoints.contains_key(&tip) {
            return Ok(());
        }
        let cp = proposed.checkpoints.get(&tip).ok_or_else(|| SemioError::InvalidOperation("missing tip checkpoint".into()))?.clone();
        for ch in &cp.changes {
            if let Err(e) = KitChange::apply_forward(ch, sync) {
                conflicts.insert(KitConflict { id: cp.id.clone(), wip_checkpoint: cp.clone(), backbone_tip: auth.the_kit_head.clone(), reason: e.to_string(), created_at: Utc::now().to_rfc3339() });
                return Ok(());
            }
        }
        {
            let mut g = sync.write().map_err(|_| SemioError::LockPoisoned("sync"))?;
            g.checkpoints.insert(cp.id.clone(), cp.clone());
            g.children = KitCheckpoint::rebuild_children_map(&g.checkpoints);
            g.the_kit_head = Some(cp.id.clone());
        }
        match backbone.persist_full(proposed)? {
            ProposeOutcome::Accepted => {
                let new_auth = backbone.pull()?;
                let (tx, rx) = std::sync::mpsc::channel();
                wip_tx.send(WipMsg::ApplyAuth { snap: new_auth, reply: tx }).map_err(|_| SemioError::InvalidOperation("wip channel closed".into()))?;
                rx.recv().map_err(|_| SemioError::InvalidOperation("wip apply auth".into()))?.map_err(|e| SemioError::InvalidOperation(e.to_string()))?;
            }
            ProposeOutcome::Rejected { .. } => {}
        }
        Ok(())
    }

    pub fn run(backbone_slot: Arc<Mutex<Option<BackboneKind>>>, sync: KitGraphRef, pending: Arc<Mutex<usize>>, conflicts: Arc<ConflictRegistry>, wip_tx: std::sync::mpsc::Sender<WipMsg>, rx: Receiver<CoordMsg>) {
        while let Ok(msg) = rx.recv() {
            match msg {
                CoordMsg::WipProposal { proposed, reply } => {
                    {
                        let mut p = pending.lock().expect("p");
                        *p += 1;
                    }
                    let res = (|| {
                        let g = backbone_slot.lock().expect("bb");
                        let Some(ref b) = *g else {
                            return Ok(());
                        };
                        process_proposal(b, &sync, &conflicts, &proposed, &wip_tx)
                    })();
                    {
                        let mut p = pending.lock().expect("p");
                        *p = p.saturating_sub(1);
                    }
                    if let Some(tx) = reply {
                        let _ = tx.send(res);
                    }
                }
                CoordMsg::SyncNow => {}
                CoordMsg::Attach { cfg, reply } => {
                    let r = BackboneKind::from_config(&cfg).and_then(|k| {
                        let mut g = backbone_slot.lock().expect("bb");
                        *g = Some(k);
                        Ok(())
                    });
                    let _ = reply.send(r);
                }
                CoordMsg::Detach { reply } => {
                    let mut g = backbone_slot.lock().expect("bb");
                    *g = None;
                    let _ = reply.send(());
                }
                CoordMsg::Status { reply } => {
                    let g = backbone_slot.lock().expect("bb");
                    let (attached, kind, tip) = match &*g {
                        None => (false, None, None),
                        Some(b) => {
                            let t = b.pull().ok().and_then(|s| s.the_kit_head);
                            (true, Some(b.kind_name().to_string()), t)
                        }
                    };
                    let pend = *pending.lock().expect("p");
                    let _ = reply.send(crate::backbone::BackboneStatusDto { attached, kind, backbone_tip: tip, pending_wip_checkpoints: pend });
                }
                CoordMsg::SetActiveCheckpoint { id, reply } => {
                    let r = (|| {
                        let g = backbone_slot.lock().expect("bb");
                        let Some(ref b) = *g else {
                            return Err(SemioError::InvalidOperation("no backbone attached".into()));
                        };
                        b.set_active_checkpoint(id.as_ref())
                    })();
                    let _ = reply.send(r);
                }
                CoordMsg::ResolveConflict { id, strategy, wip, reply } => {
                    let r = (|| {
                        let _c = conflicts.remove(&id).ok_or_else(|| SemioError::NotFound { kind: "KitConflict", id: id.clone() })?;
                        match strategy {
                            crate::kit_conflict_registry::ConflictResolution::DropWip => Ok(()),
                            crate::kit_conflict_registry::ConflictResolution::ForceOverwriteBackbone => {
                                let g = backbone_slot.lock().expect("bb");
                                let Some(ref b) = *g else {
                                    return Err(SemioError::InvalidOperation("no backbone".into()));
                                };
                                let auth = b.pull()?;
                                apply_snap_to_graph(&wip, &auth).map_err(|e| SemioError::InvalidOperation(e.to_string()))
                            }
                        }
                    })();
                    let _ = reply.send(r);
                }
            }
        }
    }
}

#[cfg(not(target_arch = "wasm32"))]
pub mod kit_store {
    use std::sync::mpsc;
    use std::sync::{Arc, Mutex};
    use std::thread::JoinHandle;

    use async_broadcast::Receiver;

    use crate::backbone::BackboneConfig;
    use crate::error::{Result, SemioError};
    use crate::kit_conflict_registry::{ConflictRegistry, ConflictResolution, KitConflict};
    use crate::kit_graph::{KitFullDto, KitGraph, KitGraphRef};
    use crate::kit_store_command::{KitStoreCommand, KitStoreCommandResult};
    use crate::wip_kit::{CoordMsg, WipMsg};

    pub struct KitStore {
        graph: KitGraphRef,
        /// Backbone-aligned mirror graph (same `Arc` the coordinator mutates); exposed as `KitSession.authorative`.
        authorative: KitGraphRef,
        wip_tx: mpsc::Sender<WipMsg>,
        coord_tx: mpsc::Sender<CoordMsg>,
        pub conflicts: Arc<ConflictRegistry>,
        backbone_slot: Arc<Mutex<Option<crate::backbone::BackboneKind>>>,
        pending: Arc<Mutex<usize>>,
        _executor: Arc<async_executor::Executor<'static>>,
        _handles: Vec<JoinHandle<()>>,
    }

    impl KitStore {
        pub fn from_full_dto(dto: KitFullDto) -> Self {
            Self::from_graph(KitGraph::from_full_dto(dto))
        }

        pub fn from_graph(graph: KitGraphRef) -> Self {
            let conflicts = Arc::new(ConflictRegistry::new());
            let backbone_slot = Arc::new(Mutex::new(None));
            let pending = Arc::new(Mutex::new(0));
            let init = {
                let g = graph.read().expect("kit");
                g.initial.clone()
            };
            let sync = KitGraph::from_full_dto(init);
            let (wip_tx, wip_rx) = mpsc::channel::<WipMsg>();
            let (coord_tx, coord_rx) = mpsc::channel::<CoordMsg>();
            let g1 = graph.clone();
            let coord_tx_wip = coord_tx.clone();
            let t_wip = std::thread::spawn(move || {
                crate::wip_kit::run(g1, wip_rx, coord_tx_wip);
            });
            let bb = backbone_slot.clone();
            let sync_c = sync.clone();
            let pend = pending.clone();
            let conf = conflicts.clone();
            let wip_t = wip_tx.clone();
            let t_coord = std::thread::spawn(move || {
                crate::kit_coordinator::run(bb, sync_c, pend, conf, wip_t, coord_rx);
            });
            let executor = Arc::new(async_executor::Executor::new());
            let ex_run = executor.clone();
            let t_exec = std::thread::spawn(move || {
                futures_lite::future::block_on(async move {
                    let _ = ex_run.run(futures_lite::future::pending::<()>()).await;
                });
            });
            Self { graph, authorative: sync, wip_tx, coord_tx, conflicts, backbone_slot, pending, _executor: executor, _handles: vec![t_wip, t_coord, t_exec] }
        }

        pub fn graph(&self) -> KitGraphRef {
            self.graph.clone()
        }

        pub fn authorative_graph(&self) -> KitGraphRef {
            self.authorative.clone()
        }

        pub fn subscribe(&self) -> Receiver<crate::events::KitEvent> {
            self.graph.read().expect("kit").subscribe()
        }

        pub fn execute(&self, cmd: KitStoreCommand) -> Result<KitStoreCommandResult> {
            match cmd {
                KitStoreCommand::Batch { commands } => {
                    let mut out = Vec::with_capacity(commands.len());
                    for c in commands {
                        out.push(self.execute(c)?);
                    }
                    Ok(KitStoreCommandResult::Batch { results: out })
                }
                KitStoreCommand::AttachBackbone { config } => {
                    self.attach_backbone(config)?;
                    Ok(KitStoreCommandResult::AttachBackbone { ok: true })
                }
                KitStoreCommand::DetachBackbone => {
                    self.detach_backbone();
                    Ok(KitStoreCommandResult::DetachBackbone { ok: true })
                }
                KitStoreCommand::SetActiveCheckpoint { id } => {
                    self.set_active_checkpoint(id)?;
                    Ok(KitStoreCommandResult::SetActiveCheckpoint { ok: true })
                }
                KitStoreCommand::ListConflicts => Ok(KitStoreCommandResult::ListConflicts { items: self.list_conflicts() }),
                KitStoreCommand::ResolveConflict { id, strategy } => {
                    self.resolve_conflict(id, strategy)?;
                    Ok(KitStoreCommandResult::ResolveConflict { ok: true })
                }
                KitStoreCommand::BackboneStatus => {
                    let s = self.backbone_status()?;
                    Ok(KitStoreCommandResult::BackboneStatus { attached: s.attached, kind: s.kind, tip: s.backbone_tip })
                }
                KitStoreCommand::SyncNow => {
                    self.sync_now()?;
                    Ok(KitStoreCommandResult::SyncNow { ok: true })
                }
                other => {
                    let (tx, rx) = mpsc::channel();
                    self.wip_tx.send(WipMsg::Exec { cmd: other, reply: tx }).map_err(|_| SemioError::InvalidOperation("wip store closed".into()))?;
                    rx.recv().map_err(|_| SemioError::InvalidOperation("wip reply missing".into()))?
                }
            }
        }

        pub fn attach_backbone(&self, cfg: BackboneConfig) -> Result<()> {
            let (tx, rx) = mpsc::channel();
            self.coord_tx.send(CoordMsg::Attach { cfg, reply: tx }).map_err(|_| SemioError::InvalidOperation("coordinator closed".into()))?;
            rx.recv().map_err(|_| SemioError::InvalidOperation("attach reply missing".into()))?
        }

        pub fn detach_backbone(&self) {
            let (tx, rx) = mpsc::channel();
            if self.coord_tx.send(CoordMsg::Detach { reply: tx }).is_ok() {
                let _ = rx.recv();
            }
        }

        pub fn backbone_status(&self) -> Result<crate::backbone::BackboneStatusDto> {
            let (tx, rx) = mpsc::channel();
            self.coord_tx.send(CoordMsg::Status { reply: tx }).map_err(|_| SemioError::InvalidOperation("coordinator closed".into()))?;
            rx.recv().map_err(|_| SemioError::InvalidOperation("status reply missing".into()))
        }

        pub fn set_active_checkpoint(&self, id: Option<crate::id::Id>) -> Result<()> {
            let (tx, rx) = mpsc::channel();
            self.coord_tx.send(CoordMsg::SetActiveCheckpoint { id, reply: tx }).map_err(|_| SemioError::InvalidOperation("coordinator closed".into()))?;
            rx.recv().map_err(|_| SemioError::InvalidOperation("setActive reply missing".into()))?
        }

        pub fn sync_now(&self) -> Result<()> {
            self.coord_tx.send(CoordMsg::SyncNow).map_err(|_| SemioError::InvalidOperation("coordinator closed".into()))?;
            Ok(())
        }

        pub fn list_conflicts(&self) -> Vec<KitConflict> {
            self.conflicts.list()
        }

        pub fn resolve_conflict(&self, id: crate::id::Id, strategy: ConflictResolution) -> Result<()> {
            let (tx, rx) = mpsc::channel();
            self.coord_tx.send(CoordMsg::ResolveConflict { id, strategy, wip: self.graph.clone(), reply: tx }).map_err(|_| SemioError::InvalidOperation("coordinator closed".into()))?;
            rx.recv().map_err(|_| SemioError::InvalidOperation("resolve reply missing".into()))?
        }
    }
}

pub mod kit_store_command {
    //! Top-level kit store command dispatch. Commands are methods on the command
    //! types (`KitStoreCommand::execute`, `KitDraftCommand::execute`, ...); the
    //! in-memory graph (`KitStore`) is the host object they act upon.
    use serde::{Deserialize, Serialize};

    use crate::change_command::ChangeKitCommand;
    use crate::id::Id;
    use crate::kit_alternative::{KitAlternative, KitAlternativeCommand, KitAlternativeCommandResult};
    use crate::kit_change::{KitChange, KitChangeKind};
    use crate::kit_checkpoint::{KitCheckpoint, KitCheckpointCommand, KitCheckpointCommandResult};
    use crate::kit_draft::{KitDraftCommand, KitDraftCommandResult};
    use crate::kit_graph::KitGraph;
    use crate::kit_graph::KitGraphRef;
    use crate::kit_read_scope::{self, KitReadScope};
    use crate::kit_transaction::{TransactionCommand, TransactionCommandResult};
    use crate::read::{ReadKitCommand, ReadKitCommandOutput};
    use crate::{error::Result, error::SemioError};

    type KitFullDto = crate::kit_graph::KitFullDto;

    impl KitGraph {
        pub fn the_kit_dto(&self) -> KitFullDto {
            KitCheckpoint::materialize(&self.initial, &self.checkpoints, self.the_kit_head.as_ref())
        }

        pub fn materialize_at(&self, at: Option<&Id>) -> KitFullDto {
            KitCheckpoint::materialize(&self.initial, &self.checkpoints, at)
        }

        pub fn materialize_graph_at(&self, at: Option<&Id>) -> crate::kit_graph::KitGraphRef {
            KitCheckpoint::materialize_graph(&self.initial, &self.checkpoints, at)
        }

        pub fn alternative_tip(&self, aid: &Id) -> Option<Id> {
            self.alternatives.get(aid).and_then(|a| a.tip().cloned())
        }

        pub fn is_valid_draft_base(&self, cp: Option<&Id>, alt: Option<&Id>) -> bool {
            match (alt, cp) {
                (None, None) => self.the_kit_head.is_none(),
                (None, Some(c)) => self.the_kit_head.as_ref() == Some(c),
                (Some(a), Some(c)) => self.alternative_tip(a).as_ref() == Some(c),
                (Some(a), None) => self.alternatives.get(a).map(|alt| alt.checkpoints.is_empty()).unwrap_or(false),
            }
        }

        pub fn replace_live_graph(kit: &KitGraphRef, d: KitFullDto) -> Result<()> {
            KitGraph::replace_from_full_dto(kit, d).map_err(|e| SemioError::InvalidOperation(e.to_string()))
        }
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub enum KitStoreCommand {
        ReadKitCommands {
            scope: KitReadScope,
            commands: Vec<ReadKitCommand>,
        },
        NewDraft {
            #[serde(rename = "checkpointId", default, skip_serializing_if = "Option::is_none")]
            checkpoint_id: Option<Id>,
            #[serde(rename = "alternativeId", default, skip_serializing_if = "Option::is_none")]
            alternative_id: Option<Id>,
        },
        ExecuteKitDraftCommands {
            #[serde(rename = "alternativeId", default, skip_serializing_if = "Option::is_none")]
            alternative_id: Option<Id>,
            #[serde(rename = "draftId")]
            draft_id: Id,
            commands: Vec<KitDraftCommand>,
        },
        NewAlternative {
            #[serde(rename = "fromCheckpoint", default, skip_serializing_if = "Option::is_none")]
            from_checkpoint: Option<Id>,
            name: String,
        },
        ExecuteKitCheckpointCommands {
            id: Id,
            commands: Vec<KitCheckpointCommand>,
        },
        ExecuteKitAlternativeCommands {
            id: Id,
            commands: Vec<KitAlternativeCommand>,
        },
        AttachBackbone {
            config: crate::kit_backbone_wire::BackboneConfig,
        },
        DetachBackbone,
        SetActiveCheckpoint {
            #[serde(default, skip_serializing_if = "Option::is_none")]
            id: Option<Id>,
        },
        ListConflicts,
        ResolveConflict {
            id: Id,
            strategy: crate::kit_backbone_wire::ConflictResolution,
        },
        BackboneStatus,
        SyncNow,
        Batch {
            commands: Vec<KitStoreCommand>,
        },
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub enum KitStoreCommandResult {
        ReadKitCommands {
            results: Vec<ReadKitCommandOutput>,
        },
        NewDraft {
            #[serde(rename = "draftId")]
            draft_id: Id,
        },
        ExecuteKitDraftCommands {
            results: Vec<KitDraftCommandResult>,
        },
        NewAlternative {
            id: Id,
        },
        ExecuteKitCheckpointCommands {
            results: Vec<KitCheckpointCommandResult>,
        },
        ExecuteKitAlternativeCommands {
            results: Vec<KitAlternativeCommandResult>,
        },
        AttachBackbone {
            ok: bool,
        },
        DetachBackbone {
            ok: bool,
        },
        SetActiveCheckpoint {
            ok: bool,
        },
        ListConflicts {
            items: Vec<crate::kit_backbone_wire::KitConflict>,
        },
        ResolveConflict {
            ok: bool,
        },
        BackboneStatus {
            attached: bool,
            #[serde(skip_serializing_if = "Option::is_none")]
            kind: Option<String>,
            #[serde(rename = "tip")]
            tip: Option<Id>,
        },
        SyncNow {
            ok: bool,
        },
        Batch {
            results: Vec<KitStoreCommandResult>,
        },
        Nothing,
    }

    impl KitStoreCommand {
        ///
        pub fn execute(self, kit: &KitGraphRef) -> Result<KitStoreCommandResult> {
            match self {
                KitStoreCommand::AttachBackbone { config } => match config {
                    crate::kit_backbone_wire::BackboneConfig::Memory => Ok(KitStoreCommandResult::AttachBackbone { ok: true }),
                    _ => Err(SemioError::InvalidOperation("backbone attach (dev/local/remote) must be run via kit_store::KitStore::execute (semio-store control plane)".into())),
                },
                KitStoreCommand::DetachBackbone | KitStoreCommand::SetActiveCheckpoint { .. } | KitStoreCommand::ListConflicts | KitStoreCommand::ResolveConflict { .. } | KitStoreCommand::BackboneStatus | KitStoreCommand::SyncNow => {
                    Err(SemioError::InvalidOperation("backbone and conflict commands must be run via kit_store::KitStore::execute (semio-store control plane)".into()))
                }
                KitStoreCommand::Batch { commands } => {
                    let mut out = Vec::with_capacity(commands.len());
                    for c in commands {
                        out.push(c.execute(kit)?);
                    }
                    Ok(KitStoreCommandResult::Batch { results: out })
                }
                KitStoreCommand::ReadKitCommands { scope, commands } => {
                    let view = kit_read_scope::resolve_read_graph(kit, &scope)?;
                    let gr = view.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let results = ReadKitCommand::execute_many(&*gr, &commands)?;
                    Ok(KitStoreCommandResult::ReadKitCommands { results })
                }
                KitStoreCommand::NewDraft { checkpoint_id, alternative_id } => {
                    let base = {
                        let g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                        if !g.is_valid_draft_base(checkpoint_id.as_ref(), alternative_id.as_ref()) {
                            return Err(SemioError::InvalidOperation("stale or invalid draft base".into()));
                        }
                        match &alternative_id {
                            None => {
                                if g.the_kit_draft.is_some() {
                                    return Err(SemioError::InvalidOperation("kit line draft already open".into()));
                                }
                            }
                            Some(aid) => {
                                let a = g.alternatives.get(aid).ok_or_else(|| SemioError::NotFound { kind: "KitAlternative", id: aid.clone() })?;
                                if a.draft.is_some() {
                                    return Err(SemioError::InvalidOperation("alternative draft already open".into()));
                                }
                            }
                        }
                        g.materialize_at(checkpoint_id.as_ref())
                    };
                    KitGraph::replace_live_graph(kit, base.clone())?;
                    let draft = crate::kit_draft::Draft::new(checkpoint_id, alternative_id.clone(), base);
                    let draft_id = draft.id.clone();
                    let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    match alternative_id {
                        None => {
                            g.the_kit_draft = Some(draft);
                        }
                        Some(aid) => {
                            g.alternatives.get_mut(&aid).expect("checked").draft = Some(draft);
                        }
                    }
                    Ok(KitStoreCommandResult::NewDraft { draft_id })
                }
                KitStoreCommand::ExecuteKitDraftCommands { alternative_id, draft_id, commands } => {
                    let mut results = Vec::new();
                    let alt_ref = alternative_id.as_ref();
                    for c in commands {
                        results.push(c.execute(kit, alt_ref, &draft_id)?);
                    }
                    Ok(KitStoreCommandResult::ExecuteKitDraftCommands { results })
                }
                KitStoreCommand::NewAlternative { from_checkpoint, name } => {
                    let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    if let Some(ref cp) = from_checkpoint {
                        if !g.checkpoints.contains_key(cp) {
                            return Err(SemioError::NotFound { kind: "KitCheckpoint", id: cp.clone() });
                        }
                    }
                    let alt = KitAlternative::new(name, from_checkpoint);
                    let aid = alt.id.clone();
                    g.alternatives.insert(aid.clone(), alt);
                    Ok(KitStoreCommandResult::NewAlternative { id: aid })
                }
                KitStoreCommand::ExecuteKitCheckpointCommands { id, commands } => {
                    let mut results = Vec::new();
                    for c in commands {
                        results.push(c.execute(kit, &id)?);
                    }
                    Ok(KitStoreCommandResult::ExecuteKitCheckpointCommands { results })
                }
                KitStoreCommand::ExecuteKitAlternativeCommands { id, commands } => {
                    let mut results = Vec::new();
                    for c in commands {
                        results.push(c.execute(kit, &id)?);
                    }
                    Ok(KitStoreCommandResult::ExecuteKitAlternativeCommands { results })
                }
            }
        }
    }

    impl KitDraftCommand {
        pub fn execute(self, kit: &KitGraphRef, alternative_id: Option<&Id>, did: &Id) -> Result<KitDraftCommandResult> {
            match self {
                KitDraftCommand::ReadKitCommands { commands } => {
                    let sc = KitReadScope::Draft { alternative_id: alternative_id.cloned(), draft_id: did.clone() };
                    let view = kit_read_scope::resolve_read_graph(kit, &sc)?;
                    let gr = view.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let results = ReadKitCommand::execute_many(&*gr, &commands)?;
                    Ok(KitDraftCommandResult::ReadKitCommands { results })
                }
                KitDraftCommand::StartTransaction => {
                    let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let d = g.draft_mut_for_owner(alternative_id, did).ok_or_else(|| SemioError::InvalidOperation("unknown draft for transaction".into()))?;
                    let tid = d.start_transaction()?;
                    Ok(KitDraftCommandResult::StartTransaction { transaction_id: tid })
                }
                KitDraftCommand::ExecuteTransactionCommands { id: txid, commands } => {
                    let mut results = Vec::new();
                    for c in commands {
                        results.push(c.execute(kit, alternative_id, did, &txid)?);
                    }
                    Ok(KitDraftCommandResult::ExecuteTransactionCommands { results })
                }
                KitDraftCommand::FinalizeToKitCheckpoint { message } => Self::finalize_draft(kit, alternative_id, did, message),
                KitDraftCommand::Abort => {
                    let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    match alternative_id {
                        None => {
                            if g.the_kit_draft.as_ref().map(|d| d.id == *did).unwrap_or(false) {
                                g.the_kit_draft = None;
                            }
                        }
                        Some(aid) => {
                            if let Some(a) = g.alternatives.get_mut(aid) {
                                if a.draft.as_ref().map(|d| d.id == *did).unwrap_or(false) {
                                    a.draft = None;
                                }
                            }
                        }
                    }
                    Ok(KitDraftCommandResult::Abort { ok: true })
                }
                KitDraftCommand::Undo { count } => Self::draft_undo(kit, alternative_id, did, count),
                KitDraftCommand::Redo { count } => Self::draft_redo(kit, alternative_id, did, count),
                KitDraftCommand::CanUndo { count: _ } => {
                    let g = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let can = g.draft_ref_for_owner(alternative_id, did).map(|d| d.can_undo_draft()).unwrap_or(false);
                    Ok(KitDraftCommandResult::CanUndo { can })
                }
                KitDraftCommand::CanRedo { count: _ } => {
                    let g = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let can = g.draft_ref_for_owner(alternative_id, did).map(|d| d.can_redo_draft()).unwrap_or(false);
                    Ok(KitDraftCommandResult::CanRedo { can })
                }
            }
        }

        fn draft_undo(kit: &KitGraphRef, alternative_id: Option<&Id>, did: &Id, count: i32) -> Result<KitDraftCommandResult> {
            let n = if count < 0 { i32::MAX } else { count } as usize;
            for _ in 0..n {
                let tx_opt = {
                    let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let d = g.draft_mut_for_owner(alternative_id, did).ok_or_else(|| SemioError::InvalidOperation("no draft".into()))?;
                    d.pop_finalized()
                };
                let Some(tx) = tx_opt else {
                    break;
                };
                for ch in tx.changes.iter().rev() {
                    KitChange::apply_backward(ch, kit).map_err(|e| SemioError::InvalidOperation(e.to_string()))?;
                }
                let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                if let Some(d) = g.draft_mut_for_owner(alternative_id, did) {
                    d.push_redo_transaction(tx);
                }
            }
            Ok(KitDraftCommandResult::Undo { ok: true })
        }

        fn draft_redo(kit: &KitGraphRef, alternative_id: Option<&Id>, did: &Id, count: i32) -> Result<KitDraftCommandResult> {
            let n = if count < 0 { i32::MAX } else { count } as usize;
            for _ in 0..n {
                let tx_opt = {
                    let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let d = g.draft_mut_for_owner(alternative_id, did).ok_or_else(|| SemioError::InvalidOperation("no draft".into()))?;
                    d.pop_redo_transaction()
                };
                let Some(tx) = tx_opt else {
                    break;
                };
                for ch in &tx.changes {
                    KitChange::apply_forward(ch, kit).map_err(|e| SemioError::InvalidOperation(e.to_string()))?;
                }
                let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                if let Some(d) = g.draft_mut_for_owner(alternative_id, did) {
                    d.push_finalized(tx);
                }
            }
            Ok(KitDraftCommandResult::Redo { ok: true })
        }

        fn finalize_draft(kit: &KitGraphRef, alternative_id: Option<&Id>, did: &Id, message: String) -> Result<KitDraftCommandResult> {
            let (parent, alt, kc) = {
                let g = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                let d = g.draft_ref_for_owner(alternative_id, did).ok_or_else(|| SemioError::InvalidOperation("no draft to finalize".into()))?;
                if d.has_open_transaction() {
                    return Err(SemioError::InvalidOperation("open transaction must be closed before FinalizeToKitCheckpoint".into()));
                }
                let mut forward: Vec<crate::change_command::ChangeKitCommand> = Vec::new();
                let mut inverse: Vec<crate::change_command::ChangeKitCommand> = Vec::new();
                for tx in &d.transactions {
                    for ch in &tx.changes {
                        forward.extend(ch.flatten_forward_commands());
                    }
                }
                for tx in d.transactions.iter().rev() {
                    for ch in tx.changes.iter().rev() {
                        inverse.extend(ch.flatten_inverse_commands());
                    }
                }
                if forward.is_empty() {
                    return Err(SemioError::InvalidOperation("no change to finalize in draft".into()));
                }
                let kc = KitChange { forward, inverse, children: vec![], kind: KitChangeKind::Inferred, author: None, time: None };
                (d.parent_checkpoint.clone(), d.target_alternative.clone(), kc)
            };
            if alt.is_some() {
                // branch, then roll the live graph back to the main-line parent checkpoint.
                KitChange::apply_backward(&kc, kit).map_err(|e| SemioError::InvalidOperation(e.to_string()))?;
            }
            let cp = KitCheckpoint::new(parent.clone(), vec![kc], Some(message));
            let new_id = cp.id.clone();
            {
                let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                g.checkpoints.insert(new_id.clone(), cp);
                g.children.entry(parent.clone()).or_default().push(new_id.clone());
                match &alt {
                    Some(aid) => {
                        if let Some(a) = g.alternatives.get_mut(aid) {
                            a.append(new_id.clone());
                        } else {
                            return Err(SemioError::InvalidOperation("target alternative missing".into()));
                        }
                        if let Some(a) = g.alternatives.get_mut(aid) {
                            if a.draft.as_ref().map(|d| d.id == *did).unwrap_or(false) {
                                a.draft = None;
                            }
                        }
                    }
                    None => {
                        g.the_kit_head = Some(new_id.clone());
                        if g.the_kit_draft.as_ref().map(|d| d.id == *did).unwrap_or(false) {
                            g.the_kit_draft = None;
                        }
                    }
                }
            }
            Ok(KitDraftCommandResult::FinalizeToKitCheckpoint { checkpoint_id: new_id })
        }
    }

    impl TransactionCommand {
        pub fn execute(self, kit: &KitGraphRef, alternative_id: Option<&Id>, did: &Id, txid: &Id) -> Result<TransactionCommandResult> {
            match self {
                TransactionCommand::ReadKitCommands { commands } => {
                    let sc = KitReadScope::Transaction { alternative_id: alternative_id.cloned(), draft_id: did.clone(), transaction_id: txid.clone() };
                    let view = kit_read_scope::resolve_read_graph(kit, &sc)?;
                    let gr = view.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let results = ReadKitCommand::execute_many(&*gr, &commands)?;
                    Ok(TransactionCommandResult::ReadKitCommands { results })
                }
                TransactionCommand::ChangeKitCommands { commands: chs } => {
                    let mut n = 0usize;
                    {
                        let g = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                        let ot = g.draft_ref_for_owner(alternative_id, did).and_then(|d| d.open_transaction_ref(txid)).ok_or_else(|| SemioError::InvalidOperation("no open matching transaction".into()))?;
                        if !ot.is_open() {
                            return Err(SemioError::InvalidOperation("transaction is not open".into()));
                        }
                    }
                    for c in &chs {
                        if KitGraph::open_transaction_apply_one_command(kit, alternative_id, did, txid, c)? {
                            n += 1;
                        }
                    }
                    Ok(TransactionCommandResult::ChangeKitCommands { count: n })
                }
                TransactionCommand::Finalize => {
                    let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let d = g.draft_mut_for_owner(alternative_id, did).ok_or_else(|| SemioError::InvalidOperation("no draft".into()))?;
                    d.finalize_transaction(txid)?;
                    Ok(TransactionCommandResult::Finalize { ok: true })
                }
                TransactionCommand::Abort => {
                    let tx = {
                        let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                        let d = g.draft_mut_for_owner(alternative_id, did).ok_or_else(|| SemioError::InvalidOperation("no draft".into()))?;
                        d.take_open_transaction(txid)?
                    };
                    for ch in tx.changes.iter().rev() {
                        KitChange::apply_backward(ch, kit).map_err(|e| SemioError::InvalidOperation(e.to_string()))?;
                    }
                    Ok(TransactionCommandResult::Abort { ok: true })
                }
                TransactionCommand::Undo => Self::tx_undo(kit, alternative_id, did, txid, false),
                TransactionCommand::UndoAll => Self::tx_undo(kit, alternative_id, did, txid, true),
                TransactionCommand::Redo => Self::tx_redo(kit, alternative_id, did, txid, false),
                TransactionCommand::RedoAll => Self::tx_redo(kit, alternative_id, did, txid, true),
                TransactionCommand::CanUndo => {
                    let g = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let can = g.draft_ref_for_owner(alternative_id, did).and_then(|d| d.open_transaction_ref(txid)).map(|t| t.can_undo()).unwrap_or(false);
                    Ok(TransactionCommandResult::CanUndo { can })
                }
                TransactionCommand::CanRedo => {
                    let g = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let can = g.draft_ref_for_owner(alternative_id, did).and_then(|d| d.open_transaction_ref(txid)).map(|t| t.can_redo()).unwrap_or(false);
                    Ok(TransactionCommandResult::CanRedo { can })
                }
            }
        }

        fn tx_undo(kit: &KitGraphRef, alternative_id: Option<&Id>, did: &Id, txid: &Id, all: bool) -> Result<TransactionCommandResult> {
            loop {
                let done = {
                    let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let tx = g.draft_mut_for_owner(alternative_id, did).and_then(|d| d.open_transaction_mut(txid)).ok_or_else(|| SemioError::InvalidOperation("no tx for undo".into()))?;
                    if !tx.can_undo() {
                        return Ok(if all { TransactionCommandResult::UndoAll { ok: true } } else { TransactionCommandResult::Undo { ok: true } });
                    }
                    tx.changes.pop()
                };
                let Some(ch) = done else {
                    break;
                };
                KitChange::apply_backward(&ch, kit).map_err(|e| SemioError::InvalidOperation(e.to_string()))?;
                {
                    let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let tx = g.draft_mut_for_owner(alternative_id, did).and_then(|d| d.open_transaction_mut(txid)).expect("tx");
                    tx.redo_changes.push(ch);
                }
                if !all {
                    return Ok(TransactionCommandResult::Undo { ok: true });
                }
            }
            Ok(TransactionCommandResult::UndoAll { ok: true })
        }

        fn tx_redo(kit: &KitGraphRef, alternative_id: Option<&Id>, did: &Id, txid: &Id, all: bool) -> Result<TransactionCommandResult> {
            loop {
                let done = {
                    let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let tx = g.draft_mut_for_owner(alternative_id, did).and_then(|d| d.open_transaction_mut(txid)).ok_or_else(|| SemioError::InvalidOperation("no tx for redo".into()))?;
                    if !tx.can_redo() {
                        return Ok(if all { TransactionCommandResult::RedoAll { ok: true } } else { TransactionCommandResult::Redo { ok: true } });
                    }
                    tx.redo_changes.pop()
                };
                let Some(ch) = done else {
                    break;
                };
                KitChange::apply_forward(&ch, kit).map_err(|e| SemioError::InvalidOperation(e.to_string()))?;
                {
                    let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let tx = g.draft_mut_for_owner(alternative_id, did).and_then(|d| d.open_transaction_mut(txid)).expect("tx");
                    tx.changes.push(ch);
                }
                if !all {
                    return Ok(TransactionCommandResult::Redo { ok: true });
                }
            }
            Ok(TransactionCommandResult::RedoAll { ok: true })
        }
    }

    impl KitCheckpointCommand {
        pub fn execute(self, kit: &KitGraphRef, cpid: &Id) -> Result<KitCheckpointCommandResult> {
            match self {
                KitCheckpointCommand::ReadKitCommands { commands } => {
                    let g = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let view = g.materialize_graph_at(Some(cpid));
                    let gr = view.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let results = ReadKitCommand::execute_many(&*gr, &commands)?;
                    Ok(KitCheckpointCommandResult::ReadKitCommands { results })
                }
                KitCheckpointCommand::MarkAsRelease => {
                    let init = {
                        let g = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                        g.initial.clone()
                    };
                    let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    if !g.checkpoints.contains_key(cpid) {
                        return Err(SemioError::NotFound { kind: "KitCheckpoint", id: cpid.clone() });
                    }
                    let map_snapshot = g.checkpoints.clone();
                    let cp = g.checkpoints.get_mut(cpid).expect("checked");
                    cp.mark_as_release(init, &map_snapshot);
                    Ok(KitCheckpointCommandResult::MarkAsRelease { ok: true })
                }
            }
        }
    }

    impl KitAlternativeCommand {
        pub fn execute(self, kit: &KitGraphRef, aid: &Id) -> Result<KitAlternativeCommandResult> {
            match self {
                KitAlternativeCommand::ReadKitCommands { commands } => {
                    let g = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let tip = g.alternative_tip(aid);
                    let view = match tip.as_ref() {
                        Some(t) => g.materialize_graph_at(Some(t)),
                        None => g.materialize_graph_at(g.the_kit_head.as_ref()),
                    };
                    let gr = view.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    let results = ReadKitCommand::execute_many(&*gr, &commands)?;
                    Ok(KitAlternativeCommandResult::ReadKitCommands { results })
                }
                KitAlternativeCommand::UnifyKitCheckpointsToSingleKitCheckpoint { message } => {
                    let (parent_link, before_dto, after_dto) = {
                        let g = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                        let alt = g.alternatives.get(aid).ok_or_else(|| SemioError::NotFound { kind: "KitAlternative", id: aid.clone() })?;
                        if alt.checkpoints.is_empty() {
                            return Err(SemioError::InvalidOperation("empty alternative".into()));
                        }
                        let t = alt.tip().cloned().expect("len checked");
                        let a = if let Some(r) = &alt.root { g.materialize_at(Some(r)) } else { g.materialize_at(None) };
                        let b = g.materialize_at(Some(&t));
                        (alt.root.clone(), a, b)
                    };
                    let ch = KitChange {
                        forward: vec![ChangeKitCommand::ReplaceKitFromFullDto { dto: after_dto.clone() }],
                        inverse: vec![ChangeKitCommand::ReplaceKitFromFullDto { dto: before_dto.clone() }],
                        children: vec![],
                        kind: KitChangeKind::UnifyCheckpoints,
                        author: None,
                        time: None,
                    };
                    let cp = KitCheckpoint::new(parent_link.clone(), vec![ch], Some(message));
                    let new_id = cp.id.clone();
                    let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                    g.checkpoints.insert(new_id.clone(), cp);
                    g.children.entry(parent_link.clone()).or_default().push(new_id.clone());
                    if let Some(alt) = g.alternatives.get_mut(aid) {
                        alt.collapse_to(new_id.clone());
                    }
                    Ok(KitAlternativeCommandResult::UnifyKitCheckpointsToSingleKitCheckpoint { new_checkpoint_id: new_id })
                }
            }
        }
    }
}
pub mod attribute {
    use serde::{Deserialize, Serialize};
    use std::sync::{RwLock, Weak};

    use crate::design::DesignStoreWeak;
    use crate::events::{emit_weak, EntityKind, EntityRef, EventBus, KitEvent};
    use crate::hash::{Cache, HashWriter};
    use crate::id::Id;
    use crate::kit_graph::KitGraphWeak;
    use crate::typ::TypeStoreWeak;

    use crate::connection::ConnectionStoreWeak;
    use crate::connector::ConnectorStoreWeak;
    use crate::piece::PieceStoreWeak;
    use crate::port::PortStoreWeak;
    use crate::representation::RepresentationStoreWeak;

    pub type AttributeStoreRef = std::sync::Arc<RwLock<AttributeStore>>;
    pub type AttributeStoreWeak = Weak<RwLock<AttributeStore>>;

    #[derive(Debug)]
    pub struct AttributeStore {
        pub id: Id,
        pub key: String,
        pub value: String,
        pub definition: Option<String>,
        pub parent_kit: Option<KitGraphWeak>,
        pub parent_design: Option<DesignStoreWeak>,
        pub parent_type: Option<TypeStoreWeak>,
        pub parent_piece: Option<PieceStoreWeak>,
        pub parent_port: Option<PortStoreWeak>,
        pub parent_connection: Option<ConnectionStoreWeak>,
        pub parent_representation: Option<RepresentationStoreWeak>,
        pub parent_connector: Option<ConnectorStoreWeak>,
        pub(crate) event_bus: Weak<EventBus>,
        hash_cache: Cache<String>,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq, async_graphql::SimpleObject, async_graphql::InputObject)]
    pub struct AttributeIdDto {
        pub id: Id,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq, async_graphql::SimpleObject)]
    pub struct AttributeMetadataDto {
        pub id: Id,
        pub key: String,
        pub value: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub definition: Option<String>,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq, async_graphql::SimpleObject)]
    pub struct AttributeShallowDto {
        pub id: Id,
        pub key: String,
        pub value: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub definition: Option<String>,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq, async_graphql::SimpleObject, async_graphql::InputObject)]
    pub struct AttributeFullDto {
        pub id: Id,
        pub key: String,
        pub value: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub definition: Option<String>,
    }

    impl AttributeStore {
        pub(crate) fn empty_shell(id: Id) -> Self {
            Self {
                id,
                key: String::new(),
                value: String::new(),
                definition: None,
                parent_kit: None,
                parent_design: None,
                parent_type: None,
                parent_piece: None,
                parent_port: None,
                parent_connection: None,
                parent_representation: None,
                parent_connector: None,
                event_bus: Weak::new(),
                hash_cache: Cache::default(),
            }
        }

        #[inline]
        fn emit_ev(&self, ev: KitEvent) {
            emit_weak(&self.event_bus, ev);
        }

        fn entity_ref(&self) -> EntityRef {
            EntityRef::new(EntityKind::Attribute, self.id.clone())
        }

        pub(crate) fn apply_full_dto_fields(&mut self, d: AttributeFullDto) {
            self.id = d.id;
            self.key = d.key;
            self.value = d.value;
            self.definition = d.definition;
            self.hash_cache.invalidate();
        }

        pub(crate) fn from_shallow_dto(d: AttributeShallowDto) -> Self {
            let mut s = Self::empty_shell(d.id.clone());
            s.key = d.key;
            s.value = d.value;
            s.definition = d.definition;
            s.hash_cache.invalidate();
            s
        }

        pub(crate) fn from_full_dto(d: AttributeFullDto) -> Self {
            let mut s = Self::empty_shell(d.id.clone());
            s.apply_full_dto_fields(d);
            s
        }

        pub fn set_key(&mut self, key: String) -> crate::error::SetResult {
            if let Err(e) = crate::validate::attribute_key(&key, "key") {
                self.emit_ev(KitEvent::SetRejected { event: Box::new(KitEvent::Attribute { attribute_id: self.id.clone(), event: crate::events::AttributeEvent::FieldChanged(crate::events::AttributeField::Key) }), error: e.clone() });
                return Err(e);
            }
            if self.key == key {
                return Ok(());
            }
            self.key = key;
            self.emit_ev(KitEvent::Attribute { attribute_id: self.id.clone(), event: crate::events::AttributeEvent::FieldChanged(crate::events::AttributeField::Key) });
            self.invalidate_local_and_bubble();
            Ok(())
        }

        pub fn set_value(&mut self, value: String) -> crate::error::SetResult {
            if let Err(e) = crate::validate::required_non_empty(&value, "value") {
                self.emit_ev(KitEvent::SetRejected { event: Box::new(KitEvent::Attribute { attribute_id: self.id.clone(), event: crate::events::AttributeEvent::FieldChanged(crate::events::AttributeField::Value) }), error: e.clone() });
                return Err(e);
            }
            if self.value == value {
                return Ok(());
            }
            self.value = value;
            self.emit_ev(KitEvent::Attribute { attribute_id: self.id.clone(), event: crate::events::AttributeEvent::FieldChanged(crate::events::AttributeField::Value) });
            self.invalidate_local_and_bubble();
            Ok(())
        }

        pub fn set_definition(&mut self, definition: Option<String>) -> crate::error::SetResult {
            if self.definition == definition {
                return Ok(());
            }
            self.definition = definition;
            self.emit_ev(KitEvent::Attribute { attribute_id: self.id.clone(), event: crate::events::AttributeEvent::FieldChanged(crate::events::AttributeField::Definition) });
            self.invalidate_local_and_bubble();
            Ok(())
        }

        fn invalidate_local_and_bubble(&mut self) {
            self.hash_cache.invalidate();
            self.emit_ev(KitEvent::HashInvalidated { entity: self.entity_ref() });
            if let Some(w) = &self.parent_kit {
                if let Some(k) = w.upgrade() {
                    if let Ok(k) = k.read() {
                        k.invalidate_hash();
                    }
                }
            }
            if let Some(w) = &self.parent_design {
                if let Some(d) = w.upgrade() {
                    if let Ok(d) = d.read() {
                        d.invalidate_hash();
                        d.invalidate_flatten();
                        d.invalidate_validation();
                    }
                }
            } else if let Some(w) = &self.parent_kit {
                if let Some(k) = w.upgrade() {
                    if let Ok(k) = k.read() {
                        k.invalidate_validation();
                    }
                }
            }
            if let Some(w) = &self.parent_type {
                if let Some(t) = w.upgrade() {
                    if let Ok(t) = t.read() {
                        t.invalidate_hash();
                    }
                }
            }
            if let Some(w) = &self.parent_piece {
                if let Some(p) = w.upgrade() {
                    if let Ok(p) = p.read() {
                        p.invalidate_hash();
                    }
                }
            }
            if let Some(w) = &self.parent_port {
                if let Some(p) = w.upgrade() {
                    if let Ok(p) = p.read() {
                        p.invalidate_hash();
                    }
                }
            }
            if let Some(w) = &self.parent_connection {
                if let Some(c) = w.upgrade() {
                    if let Ok(c) = c.read() {
                        c.notify_aggregate_change();
                    }
                }
            }
            if let Some(w) = &self.parent_representation {
                if let Some(r) = w.upgrade() {
                    if let Ok(r) = r.read() {
                        r.invalidate_hash();
                    }
                }
            }
            if let Some(w) = &self.parent_connector {
                if let Some(c) = w.upgrade() {
                    if let Ok(c) = c.read() {
                        c.invalidate_hash();
                    }
                }
            }
        }

        pub fn to_id_dto(&self) -> AttributeIdDto {
            AttributeIdDto { id: self.id.clone() }
        }

        pub fn to_metadata_dto(&self) -> AttributeMetadataDto {
            AttributeMetadataDto { id: self.id.clone(), key: self.key.clone(), value: self.value.clone(), definition: self.definition.clone() }
        }

        pub fn to_shallow_dto(&self) -> AttributeShallowDto {
            let m = self.to_metadata_dto();
            AttributeShallowDto { id: m.id, key: m.key, value: m.value, definition: m.definition }
        }

        pub fn to_full_dto(&self) -> AttributeFullDto {
            let m = self.to_metadata_dto();
            AttributeFullDto { id: m.id, key: m.key, value: m.value, definition: m.definition }
        }

        pub fn invalidate_hash(&self) {
            self.hash_cache.invalidate();
        }

        pub fn hash(&self) -> String {
            self.hash_cache.get_or_init(|| {
                let mut w = HashWriter::new();
                self.hash_into(&mut w);
                w.finalize()
            })
        }

        pub fn hash_into(&self, w: &mut HashWriter) {
            w.tag("attr").str(self.id.as_str()).str(&self.key).str(&self.value).opt_str(self.definition.as_deref());
        }
    }
}

