        #[inline]
        pub(crate) fn emit_ev(&self, ev: KitEvent) {
            emit_weak(&self.event_bus, ev);
        }

        pub(crate) fn rewire_piece_flatten_parents(&self) {
            let mut piece_index: HashMap<Id, PieceStoreRef> = HashMap::new();
            for piece in &self.pieces {
                if let Ok(pr) = piece.read() {
                    piece_index.insert(pr.id.clone(), piece.clone());
                }
            }

            for piece in piece_index.values() {
                if let Ok(mut pw) = piece.write() {
                    pw.set_flatten_parent_refs(None, None);
                }
            }

            if piece_index.is_empty() {
                return;
            }

            let mut adjacency: HashMap<Id, Vec<(Id, ConnectionStoreRef)>> = HashMap::new();
            for connection in &self.connections {
                let Ok(connection_read) = connection.read() else {
                    continue;
                };
                let connected_id = connection_read.connected.read().ok().and_then(|side| side.piece.upgrade().and_then(|piece| piece.read().ok().map(|piece| piece.id.clone())));
                let connecting_id = connection_read.connecting.read().ok().and_then(|side| side.piece.upgrade().and_then(|piece| piece.read().ok().map(|piece| piece.id.clone())));
                let (Some(connected_id), Some(connecting_id)) = (connected_id, connecting_id) else {
                    continue;
                };
                if !piece_index.contains_key(&connected_id) || !piece_index.contains_key(&connecting_id) {
                    continue;
                }
                adjacency.entry(connected_id.clone()).or_default().push((connecting_id.clone(), connection.clone()));
                adjacency.entry(connecting_id).or_default().push((connected_id, connection.clone()));
            }

            let roots: Vec<Id> = self.pieces.iter().filter_map(|piece| piece.read().ok().map(|piece| piece.id.clone())).collect();
            let mut visited: HashSet<Id> = HashSet::new();
            for root in roots {
                if !visited.insert(root.clone()) {
                    continue;
                }
                let mut queue = VecDeque::new();
                queue.push_back(root.clone());
                while let Some(current) = queue.pop_front() {
                    for (child_id, connection_ref) in adjacency.get(&current).cloned().unwrap_or_default() {
                        if !visited.insert(child_id.clone()) {
                            continue;
                        }
                        let Some(child_ref) = piece_index.get(&child_id) else {
                            continue;
                        };
                        let Some(parent_ref) = piece_index.get(&current) else {
                            continue;
                        };
                        if let Ok(mut child) = child_ref.write() {
                            child.set_flatten_parent_refs(Some(Arc::downgrade(parent_ref)), Some(Arc::downgrade(&connection_ref)));
                        }
                        queue.push_back(child_id);
                    }
                }
            }
        }

        pub(crate) fn entity_ref(&self) -> EntityRef {
            EntityRef::new(EntityKind::Design, self.id.clone())
        }

        pub(crate) fn apply_metadata_fields(&mut self, d: DesignMetadataDto) {
            self.id = d.id;
            self.name = d.name;
            self.description = d.description;
            self.icon = d.icon;
            self.image = d.image;
            self.location = d.location;
            self.unit = d.unit;
            self.created = d.created;
            self.updated = d.updated;
            self.hash_cache.invalidate();
            self.flatten_cache.invalidate();
        }

        pub fn invalidate_hash(&self) {
            self.invalidate_hash_local();
            if let Some(k) = self.parent_kit.upgrade() {
                if let Ok(kr) = k.read() {
                    kr.invalidate_hash();
                }
            }
        }

        pub(crate) fn invalidate_hash_local(&self) {
            self.hash_cache.invalidate();
            self.emit_ev(KitEvent::HashInvalidated { entity: self.entity_ref() });
        }

        ///
        /// `read()` (which would deadlock).
        pub fn invalidate_flatten(&self) {
            self.invalidate_flatten_with_locked_piece(None);
        }

        pub(crate) fn invalidate_flatten_with_locked_piece(&self, locked_piece: Option<Id>) {
            let design_id = self.id.clone();
            let mut piece_ids: Vec<Id> = self
                .pieces
                .iter()
                .filter_map(|p| match p.try_read() {
                    Ok(pr) => Some(pr.id.clone()),
                    Err(_) => locked_piece.clone(),
                })
                .collect();
            piece_ids.sort_by(|a, b| a.as_str().cmp(b.as_str()));
            piece_ids.dedup();
            self.flatten_cache.invalidate();
            self.emit_ev(KitEvent::FlattenInvalidated { design: design_id, pieces: piece_ids.clone() });
            for p in &self.pieces {
                if let Ok(pr) = p.try_read() {
                    pr.invalidate_flat_pose();
                }
            }
            for gid in &piece_ids {
                self.emit_ev(KitEvent::Design { design_id: self.id.clone(), event: crate::events::DesignEvent::Piece { piece_id: gid.clone(), event: crate::events::PieceEvent::DerivedChanged(crate::events::PieceField::FlatPlane) } });
                self.emit_ev(KitEvent::Design { design_id: self.id.clone(), event: crate::events::DesignEvent::Piece { piece_id: gid.clone(), event: crate::events::PieceEvent::DerivedChanged(crate::events::PieceField::FlatCenter) } });
            }
        }

        pub fn invalidate_validation(&self) {
            if let Some(k) = self.parent_kit.upgrade() {
                if let Ok(k) = k.read() {
                    k.invalidate_validation();
                }
            }
        }

        pub(crate) fn bubble_to_kit(&self) {
            if let Some(k) = self.parent_kit.upgrade() {
                if let Ok(k) = k.read() {
                    k.invalidate_hash();
                    k.invalidate_validation();
                }
            }
        }

        pub fn set_name(&mut self, name: String) -> crate::error::SetResult {
            let name = name.trim().to_string();
            if let Err(e) = crate::validate::required_name(&name, "name") {
                self.emit_ev(KitEvent::SetRejected { event: Box::new(KitEvent::Design { design_id: self.id.clone(), event: crate::events::DesignEvent::FieldChanged(crate::events::DesignField::Name) }), error: e.clone() });
                return Err(e);
            }
            if self.name == name {
                return Ok(());
            }
            self.name = name;
            self.emit_ev(KitEvent::Design { design_id: self.id.clone(), event: crate::events::DesignEvent::FieldChanged(crate::events::DesignField::Name) });
            self.hash_cache.invalidate();
            self.emit_ev(KitEvent::HashInvalidated { entity: self.entity_ref() });
            self.invalidate_flatten();
            self.bubble_to_kit();
            Ok(())
        }

        pub fn set_description(&mut self, v: Option<String>) -> crate::error::SetResult {
            let v = match v {
                None => None,
                Some(s) if s.trim().is_empty() => None,
                Some(s) => Some(s.trim().to_string()),
            };
            if self.description == v {
                return Ok(());
            }
            self.description = v;
            self.emit_ev(KitEvent::Design { design_id: self.id.clone(), event: crate::events::DesignEvent::FieldChanged(crate::events::DesignField::Description) });
            self.hash_cache.invalidate();
            self.emit_ev(KitEvent::HashInvalidated { entity: self.entity_ref() });
            self.invalidate_flatten();
            self.bubble_to_kit();
            Ok(())
        }

