pub mod kit_diff {
    use serde::{Deserialize, Serialize};
    use std::collections::{HashMap, HashSet};

    use crate::attribute::AttributeIdDto;
    use crate::author::{AuthorFullDto, AuthorIdDto};
    use crate::concept::ConceptIdDto;
    use crate::design::{DesignFullDto, DesignIdDto};
    use crate::diff::{merge_opt, merge_opt_nested, AttributesDiff, AuthorsDiff, ConceptsDiff, DesignDiff, FamiliesDiff, FilesDiff, FoldersDiff, PropsDiff, QualitiesDiff, TagsDiff, TypesDiff};
    use crate::family::FamilyIdDto;
    use crate::file::FileIdDto;
    use crate::folder::FolderIdDto;
    use crate::id::Id;
    use crate::kit_graph::KitFullDto;
    use crate::prop::PropIdDto;
    use crate::quality::QualityIdDto;
    use crate::tag::TagIdDto;
    use crate::typ::TypeIdDto;

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq)]
    #[serde(rename_all = "camelCase")]
    pub struct DesignDiffUpdate {
        #[serde(rename = "designId")]
        pub design_id: Id,
        #[serde(flatten)]
        pub diff: DesignDiff,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq)]
    #[serde(rename_all = "camelCase")]
    pub struct DesignsDiff {
        #[serde(default)]
        pub removed: Vec<DesignIdDto>,
        #[serde(default)]
        pub updated: Vec<DesignDiffUpdate>,
        #[serde(default)]
        pub added: Vec<DesignFullDto>,
    }

    impl DesignsDiff {
        pub fn is_empty(&self) -> bool {
            self.removed.is_empty() && self.updated.is_empty() && self.added.is_empty()
        }
        pub fn merge(&self, b: &Self) -> Self {
            let mut removed: Vec<_> = self.removed.iter().chain(b.removed.iter()).cloned().collect();
            removed.sort_by(|x, y| x.id.cmp(&y.id));
            removed.dedup_by(|x, y| x.id == y.id);
            let mut m: HashMap<Id, DesignDiffUpdate> = HashMap::new();
            for u in &self.updated {
                m.insert(u.design_id.clone(), u.clone());
            }
            for u in &b.updated {
                let e = m.entry(u.design_id.clone()).or_insert_with(|| DesignDiffUpdate { design_id: u.design_id.clone(), diff: DesignDiff::default() });
                e.diff = e.diff.merge(&u.diff);
            }
            Self { removed, updated: m.into_values().collect(), added: [self.added.as_slice(), b.added.as_slice()].concat() }
        }
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq)]
    #[serde(rename_all = "camelCase")]
    pub struct KitDiff {
        pub name: Option<String>,
        pub description: Option<Option<String>>,
        pub icon: Option<Option<String>>,
        pub image: Option<Option<String>>,
        pub preview: Option<Option<String>>,
        pub remote: Option<Option<String>>,
        pub homepage: Option<Option<String>>,
        pub license: Option<Option<String>>,
        pub uri: Option<Option<String>>,
        pub created: Option<Option<String>>,
        pub updated: Option<Option<String>>,
        #[serde(default)]
        pub types: Option<TypesDiff>,
        #[serde(default)]
        pub families: Option<FamiliesDiff>,
        #[serde(default)]
        pub designs: Option<DesignsDiff>,
        #[serde(default)]
        pub files: Option<FilesDiff>,
        #[serde(default)]
        pub folders: Option<FoldersDiff>,
        #[serde(default)]
        pub authors: Option<AuthorsDiff>,
        #[serde(default)]
        pub concepts: Option<ConceptsDiff>,
        #[serde(default)]
        pub tags: Option<TagsDiff>,
        #[serde(default)]
        pub qualities: Option<QualitiesDiff>,
        #[serde(default)]
        pub props: Option<PropsDiff>,
        #[serde(default)]
        pub attributes: Option<AttributesDiff>,
    }

    impl KitDiff {
        pub fn between(before: &KitFullDto, after: &KitFullDto) -> Self {
            Self::between_dto(before, after)
        }

        pub fn is_empty(&self) -> bool {
            self.name.is_none()
                && self.description.is_none()
                && self.icon.is_none()
                && self.image.is_none()
                && self.preview.is_none()
                && self.remote.is_none()
                && self.homepage.is_none()
                && self.license.is_none()
                && self.uri.is_none()
                && self.created.is_none()
                && self.updated.is_none()
                && self.types.as_ref().map_or(true, |x| x.is_empty())
                && self.families.as_ref().map_or(true, |x| x.is_empty())
                && self.designs.as_ref().map_or(true, |x| x.is_empty())
                && self.files.as_ref().map_or(true, |x| x.is_empty())
                && self.folders.as_ref().map_or(true, |x| x.is_empty())
                && self.authors.as_ref().map_or(true, |x| x.is_empty())
                && self.concepts.as_ref().map_or(true, |x| x.is_empty())
                && self.tags.as_ref().map_or(true, |x| x.is_empty())
                && self.qualities.as_ref().map_or(true, |x| x.is_empty())
                && self.props.as_ref().map_or(true, |x| x.is_empty())
                && self.attributes.as_ref().map_or(true, |x| x.is_empty())
        }

        pub fn merge(&self, b: &Self) -> Self {
            Self {
                name: merge_opt(&self.name, &b.name),
                description: merge_opt_nested(&self.description, &b.description, |_, y| y.clone()),
                icon: merge_opt_nested(&self.icon, &b.icon, |_, y| y.clone()),
                image: merge_opt_nested(&self.image, &b.image, |_, y| y.clone()),
                preview: merge_opt_nested(&self.preview, &b.preview, |_, y| y.clone()),
                remote: merge_opt_nested(&self.remote, &b.remote, |_, y| y.clone()),
                homepage: merge_opt_nested(&self.homepage, &b.homepage, |_, y| y.clone()),
                license: merge_opt_nested(&self.license, &b.license, |_, y| y.clone()),
                uri: merge_opt_nested(&self.uri, &b.uri, |_, y| y.clone()),
                created: merge_opt_nested(&self.created, &b.created, |_, y| y.clone()),
                updated: merge_opt_nested(&self.updated, &b.updated, |_, y| y.clone()),
                types: merge_opt_nested(&self.types, &b.types, |x, y| x.merge(y)),
                families: merge_opt_nested(&self.families, &b.families, |x, y| x.merge(y)),
                designs: merge_opt_nested(&self.designs, &b.designs, |x, y| x.merge(y)),
                files: merge_opt_nested(&self.files, &b.files, |x, y| x.merge(y)),
                folders: merge_opt_nested(&self.folders, &b.folders, |x, y| x.merge(y)),
                authors: merge_opt_nested(&self.authors, &b.authors, |x, y| x.merge(y)),
                concepts: merge_opt_nested(&self.concepts, &b.concepts, |x, y| x.merge(y)),
                tags: merge_opt_nested(&self.tags, &b.tags, |x, y| x.merge(y)),
                qualities: merge_opt_nested(&self.qualities, &b.qualities, |x, y| x.merge(y)),
                props: merge_opt_nested(&self.props, &b.props, |x, y| x.merge(y)),
                attributes: merge_opt_nested(&self.attributes, &b.attributes, |x, y| x.merge(y)),
            }
        }

        pub fn for_design(design_id: Id, d: DesignDiff) -> Self {
            if d.is_empty() {
                return Self::default();
            }
            Self { designs: Some(DesignsDiff { removed: vec![], updated: vec![DesignDiffUpdate { design_id, diff: d }], added: vec![] }), ..Default::default() }
        }

        pub fn merge_into_baseline_dto(&self, k: &mut KitFullDto) {
            if let Some(n) = &self.name {
                k.name = n.clone();
            }
            if let Some(x) = &self.description {
                k.description = x.clone();
            }
            if let Some(x) = &self.icon {
                k.icon = x.clone();
            }
            if let Some(x) = &self.image {
                k.image = x.clone();
            }
            if let Some(x) = &self.preview {
                k.preview = x.clone();
            }
            if let Some(x) = &self.remote {
                k.remote = x.clone();
            }
            if let Some(x) = &self.homepage {
                k.homepage = x.clone();
            }
            if let Some(x) = &self.license {
                k.license = x.clone();
            }
            if let Some(x) = &self.uri {
                k.uri = x.clone();
            }
            if let Some(x) = &self.created {
                k.created = x.clone();
            }
            if let Some(x) = &self.updated {
                k.updated = x.clone();
            }
            if let Some(t) = &self.types {
                for r in &t.removed {
                    k.types.retain(|x| x.id != r.id);
                }
                for u in &t.updated {
                    if let Some(x) = k.types.iter_mut().find(|x| x.id == u.id.id) {
                        crate::diff::merge_type_diff_into_full(x, &u.diff);
                    }
                }
                k.types.extend(t.added.iter().cloned());
            }
            if let Some(f) = &self.families {
                for r in &f.removed {
                    k.families.retain(|x| x.id != r.id);
                }
                for u in &f.updated {
                    if let Some(x) = k.families.iter_mut().find(|x| x.id == u.id.id) {
                        crate::diff::merge_family_diff_into_full(x, &u.diff);
                    }
                }
                k.families.extend(f.added.iter().cloned());
            }
            if let Some(d) = &self.designs {
                for r in &d.removed {
                    k.designs.retain(|x| x.id != r.id);
                }
                for u in &d.updated {
                    if let Some(dsgn) = k.designs.iter_mut().find(|x| x.id == u.design_id) {
                        u.diff.merge_into_full_dto(dsgn);
                    }
                }
                k.designs.extend(d.added.iter().cloned());
            }
            if let Some(f) = &self.files {
                for r in &f.removed {
                    k.files.retain(|x| x.id != r.id);
                }
                for u in &f.updated {
                    if let Some(x) = k.files.iter_mut().find(|x| x.id == u.id.id) {
                        crate::diff::merge_file_diff_into_full(x, &u.diff);
                    }
                }
                k.files.extend(f.added.iter().cloned());
            }
            if let Some(fo) = &self.folders {
                for r in &fo.removed {
                    k.folders.retain(|x| x.id != r.id);
                }
                for u in &fo.updated {
                    if let Some(x) = k.folders.iter_mut().find(|x| x.id == u.id.id) {
                        crate::diff::merge_folder_diff_into_full(x, &u.diff);
                    }
                }
                k.folders.extend(fo.added.iter().cloned());
            }
            if let Some(a) = &self.authors {
                crate::diff::merge_authors_coll_into_vec(&mut k.authors, a);
            }
            if let Some(c) = &self.concepts {
                crate::diff::merge_concepts_coll_into_vec(&mut k.concepts, c);
            }
            if let Some(t) = &self.tags {
                crate::diff::merge_tags_coll_into_vec(&mut k.tags, t);
            }
            if let Some(q) = &self.qualities {
                crate::diff::merge_qualities_coll_into_vec(&mut k.qualities, q);
            }
            if let Some(p) = &self.props {
                crate::diff::merge_props_coll_into_vec(&mut k.props, p);
            }
            if let Some(a) = &self.attributes {
                crate::diff::merge_attributes_coll_into_vec(&mut k.attributes, a);
            }
        }
    }

    fn diff_id_vec<T: PartialEq + Clone>(before: &[T], after: &[T], get_id: impl Fn(&T) -> &Id) -> (Vec<T>, Vec<Id>, Vec<T>) {
        let bm: HashMap<Id, &T> = before.iter().map(|t| (get_id(t).clone(), t)).collect();
        let am: HashMap<Id, &T> = after.iter().map(|t| (get_id(t).clone(), t)).collect();
        let kb: HashSet<Id> = bm.keys().cloned().collect();
        let ka: HashSet<Id> = am.keys().cloned().collect();
        let mut added = Vec::new();
        let mut removed = Vec::new();
        let mut modified = Vec::new();
        for id in ka.difference(&kb) {
            added.push((**am.get(id).expect("a")).clone());
        }
        for id in kb.difference(&ka) {
            removed.push(id.clone());
        }
        for id in ka.intersection(&kb) {
            let b = *bm.get(id).expect("b");
            let a = *am.get(id).expect("a");
            if b != a {
                modified.push(a.clone());
            }
        }
        (added, removed, modified)
    }

    impl KitDiff {
        pub fn between_dto(before: &KitFullDto, after: &KitFullDto) -> Self {
            let mut d = Self::default();
            if before.name != after.name {
                d.name = Some(after.name.clone());
            }
            if before.description != after.description {
                d.description = Some(after.description.clone());
            }
            if before.icon != after.icon {
                d.icon = Some(after.icon.clone());
            }
            if before.image != after.image {
                d.image = Some(after.image.clone());
            }
            if before.preview != after.preview {
                d.preview = Some(after.preview.clone());
            }
            if before.remote != after.remote {
                d.remote = Some(after.remote.clone());
            }
            if before.homepage != after.homepage {
                d.homepage = Some(after.homepage.clone());
            }
            if before.license != after.license {
                d.license = Some(after.license.clone());
            }
            if before.uri != after.uri {
                d.uri = Some(after.uri.clone());
            }
            if before.created != after.created {
                d.created = Some(after.created.clone());
            }
            if before.updated != after.updated {
                d.updated = Some(after.updated.clone());
            }
            let (a_t, r_t, m_t) = diff_id_vec(&before.types, &after.types, |t| &t.id);
            if !a_t.is_empty() || !r_t.is_empty() || !m_t.is_empty() {
                d.types = Some(TypesDiff {
                    removed: r_t.iter().map(|i| TypeIdDto { id: i.clone() }).collect(),
                    updated: m_t
                        .iter()
                        .filter_map(|full| {
                            let b = before.types.iter().find(|t| t.id == full.id)?;
                            let diff = crate::diff::type_full_delta(b, full);
                            if diff.is_empty() {
                                None
                            } else {
                                Some(crate::diff::TypeDiffUpdate { id: TypeIdDto { id: full.id.clone() }, diff })
                            }
                        })
                        .collect(),
                    added: a_t,
                });
                if d.types.as_ref().unwrap().is_empty() {
                    d.types = None;
                }
            }
            let (a_fam, r_fam, m_fam) = diff_id_vec(&before.families, &after.families, |t| &t.id);
            if !a_fam.is_empty() || !r_fam.is_empty() || !m_fam.is_empty() {
                d.families = Some(FamiliesDiff {
                    removed: r_fam.iter().map(|i| FamilyIdDto { id: i.clone() }).collect(),
                    updated: m_fam
                        .iter()
                        .filter_map(|full| {
                            let b = before.families.iter().find(|t| t.id == full.id)?;
                            let df = crate::diff::family_full_delta(b, full);
                            if df.is_empty() {
                                None
                            } else {
                                Some(crate::diff::FamilyDiffUpdate { id: FamilyIdDto { id: full.id.clone() }, diff: df })
                            }
                        })
                        .collect(),
                    added: a_fam,
                });
                if d.families.as_ref().unwrap().is_empty() {
                    d.families = None;
                }
            }
            let bm: HashMap<Id, &DesignFullDto> = before.designs.iter().map(|x| (x.id.clone(), x)).collect();
            let am: HashMap<Id, &DesignFullDto> = after.designs.iter().map(|x| (x.id.clone(), x)).collect();
            let kb: HashSet<Id> = bm.keys().cloned().collect();
            let ka: HashSet<Id> = am.keys().cloned().collect();
            let mut des = DesignsDiff::default();
            for id in kb.difference(&ka) {
                des.removed.push(DesignIdDto { id: id.clone() });
            }
            for id in ka.difference(&kb) {
                des.added.push((*am.get(id).expect("a")).clone());
            }
            for id in ka.intersection(&kb) {
                let b = *bm.get(id).expect("b");
                let a = *am.get(id).expect("a");
                if b != a {
                    let dd = DesignDiff::between_dto(b, a);
                    if !dd.is_empty() {
                        des.updated.push(DesignDiffUpdate { design_id: id.clone(), diff: dd });
                    }
                }
            }
            if !des.is_empty() {
                d.designs = Some(des);
            }
            let (a_f, r_f, m_f) = diff_id_vec(&before.files, &after.files, |t| &t.id);
            if !a_f.is_empty() || !r_f.is_empty() || !m_f.is_empty() {
                d.files = Some(FilesDiff {
                    removed: r_f.iter().map(|i| FileIdDto { id: i.clone() }).collect(),
                    updated: m_f
                        .iter()
                        .filter_map(|full| {
                            let b = before.files.iter().find(|t| t.id == full.id)?;
                            let df = crate::diff::file_full_delta(b, full);
                            if df.is_empty() {
                                None
                            } else {
                                Some(crate::diff::FileDiffUpdate { id: FileIdDto { id: full.id.clone() }, diff: df })
                            }
                        })
                        .collect(),
                    added: a_f,
                });
                if d.files.as_ref().unwrap().is_empty() {
                    d.files = None;
                }
            }
            let (a_fo, r_fo, m_fo) = diff_id_vec(&before.folders, &after.folders, |t| &t.id);
            if !a_fo.is_empty() || !r_fo.is_empty() || !m_fo.is_empty() {
                d.folders = Some(FoldersDiff {
                    removed: r_fo.iter().map(|i| FolderIdDto { id: i.clone() }).collect(),
                    updated: m_fo
                        .iter()
                        .filter_map(|full| {
                            let b = before.folders.iter().find(|t| t.id == full.id)?;
                            let df = crate::diff::folder_full_delta(b, full);
                            if df.is_empty() {
                                None
                            } else {
                                Some(crate::diff::FolderDiffUpdate { id: FolderIdDto { id: full.id.clone() }, diff: df })
                            }
                        })
                        .collect(),
                    added: a_fo,
                });
                if d.folders.as_ref().unwrap().is_empty() {
                    d.folders = None;
                }
            }
            let merge_simple_authors = |bf: &[AuthorFullDto], af: &[AuthorFullDto]| -> Option<AuthorsDiff> {
                let (a, r, m) = diff_id_vec(bf, af, |t| &t.id);
                if a.is_empty() && r.is_empty() && m.is_empty() {
                    return None;
                }
                Some(AuthorsDiff {
                    removed: r.iter().map(|i| AuthorIdDto { id: i.clone() }).collect(),
                    updated: m
                        .iter()
                        .filter_map(|full| {
                            let b = bf.iter().find(|t| t.id == full.id)?;
                            let df = crate::diff::author_full_delta(b, full);
                            if df.is_empty() {
                                None
                            } else {
                                Some(crate::diff::AuthorDiffUpdate { id: AuthorIdDto { id: full.id.clone() }, diff: df })
                            }
                        })
                        .collect(),
                    added: a,
                })
            };
            d.authors = merge_simple_authors(&before.authors, &after.authors);
            d.concepts = {
                let (a, r, m) = diff_id_vec(&before.concepts, &after.concepts, |t| &t.id);
                if a.is_empty() && r.is_empty() && m.is_empty() {
                    None
                } else {
                    Some(ConceptsDiff {
                        removed: r.iter().map(|i| ConceptIdDto { id: i.clone() }).collect(),
                        updated: m
                            .iter()
                            .filter_map(|full| {
                                let b = before.concepts.iter().find(|t| t.id == full.id)?;
                                let df = crate::diff::concept_full_delta(b, full);
                                if df.is_empty() {
                                    None
                                } else {
                                    Some(crate::diff::ConceptDiffUpdate { id: ConceptIdDto { id: full.id.clone() }, diff: df })
                                }
                            })
                            .collect(),
                        added: a,
                    })
                }
            };
            d.tags = {
                let (a, r, m) = diff_id_vec(&before.tags, &after.tags, |t| &t.id);
                if a.is_empty() && r.is_empty() && m.is_empty() {
                    None
                } else {
                    Some(TagsDiff {
                        removed: r.iter().map(|i| TagIdDto { id: i.clone() }).collect(),
                        updated: m
                            .iter()
                            .filter_map(|full| {
                                let b = before.tags.iter().find(|t| t.id == full.id)?;
                                let df = crate::diff::tag_full_delta(b, full);
                                if df.is_empty() {
                                    None
                                } else {
                                    Some(crate::diff::TagDiffUpdate { id: TagIdDto { id: full.id.clone() }, diff: df })
                                }
                            })
                            .collect(),
                        added: a,
                    })
                }
            };
            d.qualities = {
                let (a, r, m) = diff_id_vec(&before.qualities, &after.qualities, |t| &t.id);
                if a.is_empty() && r.is_empty() && m.is_empty() {
                    None
                } else {
                    Some(QualitiesDiff {
                        removed: r.iter().map(|i| QualityIdDto { id: i.clone() }).collect(),
                        updated: m
                            .iter()
                            .filter_map(|full| {
                                let b = before.qualities.iter().find(|t| t.id == full.id)?;
                                let df = crate::diff::quality_full_delta(b, full);
                                if df.is_empty() {
                                    None
                                } else {
                                    Some(crate::diff::QualityDiffUpdate { id: QualityIdDto { id: full.id.clone() }, diff: df })
                                }
                            })
                            .collect(),
                        added: a,
                    })
                }
            };
            let (a_p, r_p, m_p) = diff_id_vec(&before.props, &after.props, |t| &t.id);
            if !a_p.is_empty() || !r_p.is_empty() || !m_p.is_empty() {
                let pd = PropsDiff {
                    removed: r_p.iter().map(|i| PropIdDto { id: i.clone() }).collect(),
                    updated: m_p
                        .iter()
                        .filter_map(|full| {
                            let b = before.props.iter().find(|t| t.id == full.id)?;
                            let df = crate::diff::prop_full_delta(b, full);
                            if df.is_empty() {
                                None
                            } else {
                                Some(crate::diff::PropDiffUpdate { id: PropIdDto { id: full.id.clone() }, diff: df })
                            }
                        })
                        .collect(),
                    added: a_p,
                };
                if !pd.is_empty() {
                    d.props = Some(pd);
                }
            }
            let (a_at, r_at, m_at) = diff_id_vec(&before.attributes, &after.attributes, |t| &t.id);
            if !a_at.is_empty() || !r_at.is_empty() || !m_at.is_empty() {
                let ad = AttributesDiff {
                    removed: r_at.iter().map(|i| AttributeIdDto { id: i.clone() }).collect(),
                    updated: m_at
                        .iter()
                        .filter_map(|full| {
                            let b = before.attributes.iter().find(|t| t.id == full.id)?;
                            let df = crate::diff::attribute_full_delta(b, full);
                            if df.is_empty() {
                                None
                            } else {
                                Some(crate::diff::AttributeDiffUpdate { id: AttributeIdDto { id: full.id.clone() }, diff: df })
                            }
                        })
                        .collect(),
                    added: a_at,
                };
                if !ad.is_empty() {
                    d.attributes = Some(ad);
                }
            }
            d
        }
    }
}

pub mod kit_change {
    //#region 🔖Imports
    use serde::{Deserialize, Serialize};

    use crate::change_command::{ChangeDesignCommand, ChangeKitCommand, ChangePieceCommand, ChangeTypeCommand};
    use crate::design::DesignIdDto;
    use crate::error::SemioError;
    use crate::piece::PieceIdDto;
    use crate::typ::TypeIdDto;
    //#endregion

    //#region 🔖KitChangeKind
    /// Semantic kind for a [`KitChange`] (VCS and UI; replaces the old `KitOperation` wrapper).
    #[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq, Hash, Default)]
    #[serde(rename_all = "camelCase")]
    pub enum KitChangeKind {
        #[default]
        Inferred,
        SetKitMetadata,
        AddType,
        RemoveType,
        ModifyType,
        AddDesign,
        RemoveDesign,
        ModifyDesign,
        AddPiece,
        RemovePiece,
        Connect,
        Disconnect,
        UnifyCheckpoints,
        MarkRelease,
        Other(String),
    }
    //#endregion

    //#region 🔖PieceChange
    /// 🧩 Scoped piece mutation under one design (inverse mirrors [`ChangePieceCommand::apply`] pairing).
    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub struct PieceChange {
        pub design_id: DesignIdDto,
        pub piece_id: PieceIdDto,
        pub forward: Vec<ChangePieceCommand>,
        pub inverse: Vec<ChangePieceCommand>,
        #[serde(default, skip_serializing_if = "is_default_change_kind")]
        pub kind: KitChangeKind,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub author: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub time: Option<String>,
    }

    impl PieceChange {
        pub fn apply_forward(&self, kit: &crate::kit_graph::KitGraphRef) -> Result<(), SemioError> {
            ChangeKitCommand::apply_many(
                kit,
                &[ChangeKitCommand::ChangeDesignCommands { design_id: self.design_id.clone(), commands: vec![ChangeDesignCommand::ChangePieceCommands { piece_id: self.piece_id.clone(), commands: self.forward.clone() }] }],
            )
            .map(|_| ())
        }

        pub fn apply_backward(&self, kit: &crate::kit_graph::KitGraphRef) -> Result<(), SemioError> {
            ChangeKitCommand::apply_many(
                kit,
                &[ChangeKitCommand::ChangeDesignCommands { design_id: self.design_id.clone(), commands: vec![ChangeDesignCommand::ChangePieceCommands { piece_id: self.piece_id.clone(), commands: self.inverse.clone() }] }],
            )
            .map(|_| ())
        }

        pub fn flatten_inverse_commands(&self) -> Vec<ChangeKitCommand> {
            vec![ChangeKitCommand::ChangeDesignCommands { design_id: self.design_id.clone(), commands: vec![ChangeDesignCommand::ChangePieceCommands { piece_id: self.piece_id.clone(), commands: self.inverse.clone() }] }]
        }

        pub fn flatten_forward_commands(&self) -> Vec<ChangeKitCommand> {
            vec![ChangeKitCommand::ChangeDesignCommands { design_id: self.design_id.clone(), commands: vec![ChangeDesignCommand::ChangePieceCommands { piece_id: self.piece_id.clone(), commands: self.forward.clone() }] }]
        }
    }
    //#endregion

    //#region 🔖KitDesignAtomicsBlock
    /// 🧩 Consecutive non-piece [`ChangeDesignCommand`] rows lifted with paired inverses.
    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub struct KitDesignAtomicsBlock {
        pub forward: Vec<ChangeDesignCommand>,
        pub inverse: Vec<ChangeDesignCommand>,
    }

    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase", tag = "blockKind", content = "payload")]
    pub enum KitDesignChangeBlock {
        Atomics(KitDesignAtomicsBlock),
        Piece(PieceChange),
    }
    //#endregion

    //#region 🔖KitDesignChange
    /// 🧩 Scoped design mutation tree (piece rows become [`KitDesignChangeBlock::Piece`]).
    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub struct KitDesignChange {
        pub design_id: DesignIdDto,
        pub blocks: Vec<KitDesignChangeBlock>,
        #[serde(default, skip_serializing_if = "is_default_change_kind")]
        pub kind: KitChangeKind,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub author: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub time: Option<String>,
    }

    impl KitDesignChange {
        pub fn apply_forward(&self, kit: &crate::kit_graph::KitGraphRef) -> Result<(), SemioError> {
            for b in &self.blocks {
                match b {
                    KitDesignChangeBlock::Atomics(a) => {
                        if !a.forward.is_empty() {
                            ChangeKitCommand::apply_many(kit, &[ChangeKitCommand::ChangeDesignCommands { design_id: self.design_id.clone(), commands: a.forward.clone() }]).map(|_| ())?;
                        }
                    }
                    KitDesignChangeBlock::Piece(p) => p.apply_forward(kit)?,
                }
            }
            Ok(())
        }

        pub fn apply_backward(&self, kit: &crate::kit_graph::KitGraphRef) -> Result<(), SemioError> {
            for b in self.blocks.iter().rev() {
                match b {
                    KitDesignChangeBlock::Atomics(a) => {
                        if !a.inverse.is_empty() {
                            ChangeKitCommand::apply_many(kit, &[ChangeKitCommand::ChangeDesignCommands { design_id: self.design_id.clone(), commands: a.inverse.clone() }]).map(|_| ())?;
                        }
                    }
                    KitDesignChangeBlock::Piece(p) => p.apply_backward(kit)?,
                }
            }
            Ok(())
        }

        pub fn flatten_forward_commands(&self) -> Vec<ChangeKitCommand> {
            let mut out = Vec::new();
            for b in &self.blocks {
                match b {
                    KitDesignChangeBlock::Atomics(a) => {
                        if !a.forward.is_empty() {
                            out.push(ChangeKitCommand::ChangeDesignCommands { design_id: self.design_id.clone(), commands: a.forward.clone() });
                        }
                    }
                    KitDesignChangeBlock::Piece(p) => out.extend(p.flatten_forward_commands()),
                }
            }
            out
        }

        pub fn flatten_inverse_commands(&self) -> Vec<ChangeKitCommand> {
            let mut out = Vec::new();
            for b in self.blocks.iter().rev() {
                match b {
                    KitDesignChangeBlock::Atomics(a) => {
                        if !a.inverse.is_empty() {
                            out.push(ChangeKitCommand::ChangeDesignCommands { design_id: self.design_id.clone(), commands: a.inverse.clone() });
                        }
                    }
                    KitDesignChangeBlock::Piece(p) => out.extend(p.flatten_inverse_commands()),
                }
            }
            out
        }
    }
    //#endregion

    //#region 🔖TypeChange
    /// 🧩 Scoped type mutation under one type id (wraps [`ChangeTypeCommand`] batches).
    #[derive(Clone, Debug, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    pub struct TypeChange {
        pub type_id: TypeIdDto,
        pub forward: Vec<ChangeTypeCommand>,
        pub inverse: Vec<ChangeTypeCommand>,
        #[serde(default, skip_serializing_if = "is_default_change_kind")]
        pub kind: KitChangeKind,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub author: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub time: Option<String>,
    }

    impl TypeChange {
        pub fn apply_forward(&self, kit: &crate::kit_graph::KitGraphRef) -> Result<(), SemioError> {
            ChangeKitCommand::apply_many(kit, &[ChangeKitCommand::ChangeTypeCommands { type_id: self.type_id.clone(), commands: self.forward.clone() }]).map(|_| ())
        }

        pub fn apply_backward(&self, kit: &crate::kit_graph::KitGraphRef) -> Result<(), SemioError> {
            ChangeKitCommand::apply_many(kit, &[ChangeKitCommand::ChangeTypeCommands { type_id: self.type_id.clone(), commands: self.inverse.clone() }]).map(|_| ())
        }

        pub fn flatten_forward_commands(&self) -> Vec<ChangeKitCommand> {
            vec![ChangeKitCommand::ChangeTypeCommands { type_id: self.type_id.clone(), commands: self.forward.clone() }]
        }

        pub fn flatten_inverse_commands(&self) -> Vec<ChangeKitCommand> {
            vec![ChangeKitCommand::ChangeTypeCommands { type_id: self.type_id.clone(), commands: self.inverse.clone() }]
        }
    }
    //#endregion

    //#region 🔖Change
    /// 🌳 Typed child node under [`KitChange`] (kit root is always [`KitChange`], not this enum).
    #[derive(Clone, Debug, Serialize, Deserialize)]
    pub enum Change {
        Type(TypeChange),
        Design(KitDesignChange),
        Piece(PieceChange),
    }

    impl Change {
        fn apply_forward(&self, kit: &crate::kit_graph::KitGraphRef) -> Result<(), SemioError> {
            match self {
                Change::Type(t) => t.apply_forward(kit),
                Change::Design(d) => d.apply_forward(kit),
                Change::Piece(p) => p.apply_forward(kit),
            }
        }

        fn apply_backward(&self, kit: &crate::kit_graph::KitGraphRef) -> Result<(), SemioError> {
            match self {
                Change::Type(t) => t.apply_backward(kit),
                Change::Design(d) => d.apply_backward(kit),
                Change::Piece(p) => p.apply_backward(kit),
            }
        }

        fn flatten_forward_commands(&self) -> Vec<ChangeKitCommand> {
            match self {
                Change::Type(t) => t.flatten_forward_commands(),
                Change::Design(d) => d.flatten_forward_commands(),
                Change::Piece(p) => p.flatten_forward_commands(),
            }
        }

        fn flatten_inverse_commands(&self) -> Vec<ChangeKitCommand> {
            match self {
                Change::Type(t) => t.flatten_inverse_commands(),
                Change::Design(d) => d.flatten_inverse_commands(),
                Change::Piece(p) => p.flatten_inverse_commands(),
            }
        }
    }
    //#endregion

    //#region 🔖KitChange
    fn is_default_change_kind(k: &KitChangeKind) -> bool {
        *k == KitChangeKind::Inferred
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default)]
    pub struct KitChange {
        pub forward: Vec<ChangeKitCommand>,
        pub inverse: Vec<ChangeKitCommand>,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        pub children: Vec<Change>,
        #[serde(default, skip_serializing_if = "is_default_change_kind")]
        pub kind: KitChangeKind,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub author: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub time: Option<String>,
    }

    impl KitChange {
        //#region 🔖Apply
        /// Apply the forward step to a store (depth-first: kit [`Self::forward`], then [`Self::children`]).
        pub fn apply_forward(c: &KitChange, kit: &crate::kit_graph::KitGraphRef) -> crate::error::SetResult {
            ChangeKitCommand::apply_many(kit, &c.forward).map_err(|e| crate::error::SetError::Internal(format!("kit change forward: {e}")))?;
            for ch in &c.children {
                ch.apply_forward(kit).map_err(|e| crate::error::SetError::Internal(format!("kit change child forward: {e}")))?;
            }
            Ok(())
        }

        pub fn apply_backward(c: &KitChange, kit: &crate::kit_graph::KitGraphRef) -> crate::error::SetResult {
            for ch in c.children.iter().rev() {
                ch.apply_backward(kit).map_err(|e| crate::error::SetError::Internal(format!("kit change child backward: {e}")))?;
            }
            ChangeKitCommand::apply_many(kit, &c.inverse).map_err(|e| crate::error::SetError::Internal(format!("kit change backward: {e}")))?;
            Ok(())
        }
        //#endregion

        //#region 🔖Flatten
        /// Linear forward commands equivalent to this tree (for checkpoint merge and events).
        pub fn flatten_forward_commands(&self) -> Vec<ChangeKitCommand> {
            let mut out = self.forward.clone();
            for ch in &self.children {
                out.extend(ch.flatten_forward_commands());
            }
            out
        }

        pub fn flatten_inverse_commands(&self) -> Vec<ChangeKitCommand> {
            let mut out = Vec::new();
            for ch in self.children.iter().rev() {
                out.extend(ch.flatten_inverse_commands());
            }
            out.extend(self.inverse.iter().cloned());
            out
        }
        //#endregion

        //#region 🔖Lift
        /// 🧮 Lifts a flat command batch into a typed tree using an isolated twin of `kit` (same semantics as [`ChangeKitCommand::inverse_commands_for_many`]).
        pub fn lift_flat(kit: &crate::kit_graph::KitGraphRef, forward: Vec<ChangeKitCommand>, kind: KitChangeKind, author: Option<String>, time: Option<String>) -> Result<Self, SemioError> {
            let before = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?.to_full_dto();
            let twin = crate::kit_graph::KitGraph::from_full_dto(before);
            let mut kit_forward: Vec<ChangeKitCommand> = Vec::new();
            let mut kit_inverse_groups: Vec<Vec<ChangeKitCommand>> = Vec::new();
            let mut children: Vec<Change> = Vec::new();

            for cmd in forward {
                match cmd {
                    ChangeKitCommand::ChangeTypeCommands { type_id, commands } => {
                        let inv = ChangeKitCommand::inverse_commands_for_many(&twin, &[ChangeKitCommand::ChangeTypeCommands { type_id: type_id.clone(), commands: commands.clone() }])?;
                        let inv_inner = unwrap_type_inverse(&inv, &type_id)?;
                        ChangeKitCommand::apply_many(&twin, &[ChangeKitCommand::ChangeTypeCommands { type_id: type_id.clone(), commands: commands.clone() }])?;
                        children.push(Change::Type(TypeChange { type_id, forward: commands, inverse: inv_inner, kind: KitChangeKind::Inferred, author: None, time: None }));
                    }
                    ChangeKitCommand::ChangeDesignCommands { design_id, commands } => {
                        let design_change = lift_design_change_from_commands(&twin, design_id.clone(), commands)?;
                        children.push(Change::Design(design_change));
                    }
                    other => {
                        let inv = ChangeKitCommand::inverse_commands_for_many(&twin, std::slice::from_ref(&other))?;
                        ChangeKitCommand::apply_many(&twin, std::slice::from_ref(&other))?;
                        kit_inverse_groups.push(inv);
                        kit_forward.push(other);
                    }
                }
            }

            let mut inverse: Vec<ChangeKitCommand> = Vec::new();
            for g in kit_inverse_groups.into_iter().rev() {
                inverse.extend(g);
            }

            Ok(KitChange { forward: kit_forward, inverse, children, kind, author, time })
        }
        //#endregion
    }

    //#region 🔖LiftHelpers
    fn unwrap_type_inverse(inv: &[ChangeKitCommand], expect_id: &TypeIdDto) -> Result<Vec<ChangeTypeCommand>, SemioError> {
        match inv {
            [ChangeKitCommand::ChangeTypeCommands { type_id, commands }] if type_id == expect_id => Ok(commands.clone()),
            _ => Err(SemioError::InvalidOperation("inverse for ChangeTypeCommands mismatch".into())),
        }
    }

    fn unwrap_design_inverse(inv: &[ChangeKitCommand], expect_did: &DesignIdDto) -> Result<Vec<ChangeDesignCommand>, SemioError> {
        match inv {
            [ChangeKitCommand::ChangeDesignCommands { design_id, commands }] if design_id == expect_did => Ok(commands.clone()),
            _ => Err(SemioError::InvalidOperation("inverse for ChangeDesignCommands mismatch".into())),
        }
    }

    fn lift_design_change_from_commands(twin: &crate::kit_graph::KitGraphRef, design_id: DesignIdDto, commands: Vec<ChangeDesignCommand>) -> Result<KitDesignChange, SemioError> {
        let mut blocks: Vec<KitDesignChangeBlock> = Vec::new();
        let mut buf: Vec<ChangeDesignCommand> = Vec::new();

        fn flush_atomics(twin: &crate::kit_graph::KitGraphRef, design_id: &DesignIdDto, buf: &mut Vec<ChangeDesignCommand>, blocks: &mut Vec<KitDesignChangeBlock>) -> Result<(), SemioError> {
            if buf.is_empty() {
                return Ok(());
            }
            let forward = std::mem::take(buf);
            let inv_kit = ChangeKitCommand::inverse_commands_for_many(twin, &[ChangeKitCommand::ChangeDesignCommands { design_id: design_id.clone(), commands: forward.clone() }])?;
            let inverse = unwrap_design_inverse(&inv_kit, design_id)?;
            ChangeKitCommand::apply_many(twin, &[ChangeKitCommand::ChangeDesignCommands { design_id: design_id.clone(), commands: forward.clone() }]).map(|_| ())?;
            blocks.push(KitDesignChangeBlock::Atomics(KitDesignAtomicsBlock { forward, inverse }));
            Ok(())
        }

        for cmd in commands {
            match cmd {
                ChangeDesignCommand::ChangePieceCommands { piece_id, commands: pcmds } => {
                    flush_atomics(twin, &design_id, &mut buf, &mut blocks)?;
                    let inv_kit = ChangeKitCommand::inverse_commands_for_many(
                        twin,
                        &[ChangeKitCommand::ChangeDesignCommands { design_id: design_id.clone(), commands: vec![ChangeDesignCommand::ChangePieceCommands { piece_id: piece_id.clone(), commands: pcmds.clone() }] }],
                    )?;
                    let inv_cmds = unwrap_piece_inverse(&inv_kit, &design_id, &piece_id)?;
                    ChangeKitCommand::apply_many(twin, &[ChangeKitCommand::ChangeDesignCommands { design_id: design_id.clone(), commands: vec![ChangeDesignCommand::ChangePieceCommands { piece_id: piece_id.clone(), commands: pcmds.clone() }] }])
                        .map(|_| ())?;
                    blocks.push(KitDesignChangeBlock::Piece(PieceChange { design_id: design_id.clone(), piece_id, forward: pcmds, inverse: inv_cmds, kind: KitChangeKind::Inferred, author: None, time: None }));
                }
                other => buf.push(other),
            }
        }
        flush_atomics(twin, &design_id, &mut buf, &mut blocks)?;

        Ok(KitDesignChange { design_id, blocks, kind: KitChangeKind::Inferred, author: None, time: None })
    }

    fn unwrap_piece_inverse(inv: &[ChangeKitCommand], expect_did: &DesignIdDto, expect_pid: &PieceIdDto) -> Result<Vec<ChangePieceCommand>, SemioError> {
        let cmds = unwrap_design_inverse(inv, expect_did)?;
        match cmds.as_slice() {
            [ChangeDesignCommand::ChangePieceCommands { piece_id, commands }] if piece_id == expect_pid => Ok(commands.clone()),
            _ => Err(SemioError::InvalidOperation("inverse for ChangePieceCommands mismatch".into())),
        }
    }
    //#endregion
}

pub mod error {
    use serde::{Deserialize, Serialize};
    use thiserror::Error;

    use crate::id::Id;

    #[derive(Error, Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    #[serde(tag = "kind", content = "message")]
    pub enum SetError {
        #[error("illegal name: {0}")]
        IllegalName(String),
        #[error("name too long: {0}")]
        NameTooLong(String),
        #[error("invalid url: {0}")]
        InvalidUrl(String),
        #[error("invalid value: {0}")]
        InvalidValue(String),
        #[error("duplicate id: {0}")]
        DuplicateId(String),
        #[error("not found: {0}")]
        NotFound(String),
        #[error("cyclic reference: {0}")]
        CyclicReference(String),
        #[error("port family mismatch: {0}")]
        PortFamilyMismatch(String),
        #[error("readonly: {0}")]
        Readonly(String),
        #[error("disposed: {0}")]
        Disposed(String),
        #[error("timeout: {0}")]
        Timeout(String),
        #[error("lock poisoned: {0}")]
        LockPoisoned(String),
        #[error("internal: {0}")]
        Internal(String),
    }

    pub type SetResult = std::result::Result<(), SetError>;

    #[derive(Error, Debug)]
    pub enum SemioError {
        #[error("entity not found: {kind} '{id}'")]
        NotFound { kind: &'static str, id: Id },

        #[error("invalid operation: {0}")]
        InvalidOperation(String),

        #[error("lock poisoned accessing {0}")]
        LockPoisoned(&'static str),

        #[error("json error: {0}")]
        Json(#[from] serde_json::Error),

        #[error("io error: {0}")]
        Io(#[from] std::io::Error),

        #[cfg(not(target_arch = "wasm32"))]
        #[error("sqlite error: {0}")]
        Sqlite(#[from] rusqlite::Error),

        #[cfg(not(target_arch = "wasm32"))]
        #[error("zip error: {0}")]
        Zip(#[from] zip::result::ZipError),

        #[error("other: {0}")]
        Other(String),
    }

    pub type Result<T> = std::result::Result<T, SemioError>;

    impl From<SetError> for SemioError {
        fn from(e: SetError) -> Self {
            SemioError::InvalidOperation(e.to_string())
        }
    }
}

pub mod validate {
    //! 🧾 Field-level validation helpers returning [`crate::error::SetError`].

    use crate::error::{SetError, SetResult};

    const MAX_NAME_LEN: usize = 512;
    const MAX_KEY_LEN: usize = 256;
    const MAX_URL_LEN: usize = 4096;

    pub fn required_name(s: &str, label: &str) -> SetResult {
        let t = s.trim();
        if t.is_empty() {
            return Err(SetError::IllegalName(format!("{label} cannot be empty")));
        }
        if t.len() > MAX_NAME_LEN {
            return Err(SetError::NameTooLong(format!("{label} exceeds {MAX_NAME_LEN} chars")));
        }
        Ok(())
    }

    pub fn optional_display_name(s: &Option<String>, label: &str) -> SetResult {
        match s {
            None => Ok(()),
            Some(x) => {
                let t = x.trim();
                if t.is_empty() {
                    return Err(SetError::IllegalName(format!("{label} cannot be empty")));
                }
                if t.len() > MAX_NAME_LEN {
                    return Err(SetError::NameTooLong(format!("{label} exceeds {MAX_NAME_LEN} chars")));
                }
                Ok(())
            }
        }
    }

    pub fn required_non_empty(s: &str, label: &str) -> SetResult {
        if s.trim().is_empty() {
            return Err(SetError::InvalidValue(format!("{label} cannot be empty")));
        }
        Ok(())
    }

    pub fn required_url(s: &str, label: &str) -> SetResult {
        let t = s.trim();
        if t.is_empty() {
            return Err(SetError::InvalidUrl(format!("{label} cannot be empty")));
        }
        if t.len() > MAX_URL_LEN {
            return Err(SetError::InvalidUrl(format!("{label} exceeds {MAX_URL_LEN} chars")));
        }
        if t.starts_with('/') || t.starts_with("./") {
            return Ok(());
        }
        if t.contains("://") {
            return Ok(());
        }
        Err(SetError::InvalidUrl(format!("{label} must be a URL or path")))
    }

    pub fn optional_url(s: &Option<String>, label: &str) -> SetResult {
        match s {
            None => Ok(()),
            Some(u) => {
                if u.trim().is_empty() {
                    return Ok(());
                }
                required_url(u, label)
            }
        }
    }

    pub fn optional_opaque_uri(s: &Option<String>, label: &str) -> SetResult {
        match s {
            None => Ok(()),
            Some(u) => {
                let t = u.trim();
                if t.is_empty() {
                    return Ok(());
                }
                if t.len() > MAX_URL_LEN {
                    return Err(SetError::InvalidUrl(format!("{label} exceeds {MAX_URL_LEN} chars")));
                }
                Ok(())
            }
        }
    }

    pub fn email_basic(s: &str, label: &str) -> SetResult {
        let t = s.trim();
        if t.is_empty() {
            return Err(SetError::InvalidValue(format!("{label} cannot be empty")));
        }
        if !t.contains('@') || t.len() < 3 {
            return Err(SetError::InvalidValue(format!("{label} must look like an email")));
        }
        Ok(())
    }

    pub fn attribute_key(s: &str, label: &str) -> SetResult {
        let t = s.trim();
        if t.is_empty() {
            return Err(SetError::IllegalName(format!("{label} cannot be empty")));
        }
        if t.len() > MAX_KEY_LEN {
            return Err(SetError::NameTooLong(format!("{label} exceeds {MAX_KEY_LEN} chars")));
        }
        Ok(())
    }
}

