        pub fn hash(&self) -> String {
            self.hash_cache
                .get_or_init(|| {
                    let mut w = HashWriter::new();
                    self.hash_into(&mut w);
                    w.finalize()
                })
                .clone()
        }

        pub fn hash_into(&self, w: &mut HashWriter) {
            w.tag("kit").str(self.id.as_str()).str(&self.name).opt_str(self.description.as_deref()).opt_str(self.license.as_deref());
            for t in &self.types {
                if let Ok(t) = t.read() {
                    t.hash_into(w);
                }
            }
            for d in &self.designs {
                if let Ok(d) = d.read() {
                    d.hash_into(w);
                }
            }
            for f in &self.files {
                if let Ok(f) = f.read() {
                    f.hash_into(w);
                }
            }
            for f in &self.folders {
                if let Ok(f) = f.read() {
                    f.hash_into(w);
                }
            }
            for a in &self.authors {
                if let Ok(a) = a.read() {
                    a.hash_into(w);
                }
            }
            for c in &self.concepts {
                if let Ok(c) = c.read() {
                    c.hash_into(w);
                }
            }
            for t in &self.tags {
                if let Ok(t) = t.read() {
                    t.hash_into(w);
                }
            }
            for q in &self.qualities {
                if let Ok(q) = q.read() {
                    q.hash_into(w);
                }
            }
            for p in &self.props {
                if let Ok(p) = p.read() {
                    p.hash_into(w);
                }
            }
            for a in &self.attributes {
                if let Ok(a) = a.read() {
                    a.hash_into(w);
                }
            }
        }

        pub fn semio_type(&self, id: &str) -> Option<TypeStoreRef> {
            self.types.iter().find(|t| t.read().map(|t| t.id.as_str() == id).unwrap_or(false)).cloned()
        }

        pub fn design(&self, id: &str) -> Option<DesignStoreRef> {
            self.designs.iter().find(|d| d.read().map(|d| d.id.as_str() == id).unwrap_or(false)).cloned()
        }

        #[allow(dead_code)]
        pub(crate) fn find_design_id_for_piece(&self, piece_id: &Id) -> Option<String> {
            for d in &self.designs {
                if let Ok(dr) = d.read() {
                    if dr.piece(piece_id.as_str()).is_some() {
                        return Some(dr.id.to_string());
                    }
                }
            }
            None
        }

        pub fn file(&self, id: &str) -> Option<FileStoreRef> {
            self.files.iter().find(|f| f.read().map(|f| f.id.as_str() == id).unwrap_or(false)).cloned()
        }

        pub fn folder(&self, id: &str) -> Option<FolderStoreRef> {
            self.folders.iter().find(|f| f.read().map(|f| f.id.as_str() == id).unwrap_or(false)).cloned()
        }

        pub fn quality(&self, id: &str) -> Option<QualityStoreRef> {
            self.qualities.iter().find(|q| q.read().map(|q| q.id.as_str() == id).unwrap_or(false)).cloned()
        }

        pub fn flatten_design(&self, design_id: &str) -> Result<SemioReport<crate::diff::DesignChange>> {
            let d = self.design(design_id).ok_or_else(|| SemioError::NotFound { kind: "Design", id: Id::from(design_id) })?;
            let mut dw = d.write().map_err(|_| SemioError::LockPoisoned("design"))?;
            Ok(dw.flatten_change())
        }

        pub fn semantic_add_design_piece(&mut self, design_id: &str, piece: crate::piece::PieceFullDto) -> Result<()> {
            let dref = self.design(design_id).ok_or_else(|| SemioError::NotFound { kind: "Design", id: Id::from(design_id) })?;
            let type_index: HashMap<Id, TypeStoreRef> = self.types.iter().filter_map(|t| t.read().ok().map(|r| (r.id.clone(), t.clone()))).collect();
            let design_weak = Arc::downgrade(&dref);
            dref.write().map_err(|_| SemioError::LockPoisoned("design"))?.semantic_add_piece(piece, &type_index, design_weak)?;
            self.invalidate_hash();
            self.invalidate_validation();
            Ok(())
        }

        pub fn semantic_remove_design_pieces(&mut self, design_id: &str, piece_ids: &[Id]) -> Result<()> {
            if piece_ids.is_empty() {
                return Ok(());
            }
            let dref = self.design(design_id).ok_or_else(|| SemioError::NotFound { kind: "Design", id: Id::from(design_id) })?;
            dref.write().map_err(|_| SemioError::LockPoisoned("design"))?.delete_pieces(piece_ids);
            self.invalidate_hash();
            self.invalidate_validation();
            Ok(())
        }

        pub fn semantic_remove_design_connection(&mut self, design_id: &str, connection_id: &Id) -> Result<()> {
            let dref = self.design(design_id).ok_or_else(|| SemioError::NotFound { kind: "Design", id: Id::from(design_id) })?;
            dref.write().map_err(|_| SemioError::LockPoisoned("design"))?.semantic_remove_connection(connection_id)?;
            self.invalidate_hash();
            self.invalidate_validation();
            Ok(())
        }

        pub fn semantic_add_design_connection(&mut self, design_id: &str, c: crate::connection::ConnectionFullDto) -> Result<()> {
            let dref = self.design(design_id).ok_or_else(|| SemioError::NotFound { kind: "Design", id: Id::from(design_id) })?;
            let design_weak = Arc::downgrade(&dref);
            dref.write().map_err(|_| SemioError::LockPoisoned("design"))?.semantic_add_connection(c, design_weak)?;
            self.invalidate_hash();
            self.invalidate_validation();
            Ok(())
        }

        pub fn parse_entity_kind(s: &str) -> std::result::Result<EntityKind, SetError> {
            match s {
                "Kit" => Ok(EntityKind::Kit),
                "Type" => Ok(EntityKind::Type),
                "Design" => Ok(EntityKind::Design),
                "Piece" => Ok(EntityKind::Piece),
                "Connection" => Ok(EntityKind::Connection),
                "Side" => Ok(EntityKind::Side),
                "Port" => Ok(EntityKind::Port),
                "Connector" => Ok(EntityKind::Connector),
                "Representation" => Ok(EntityKind::Representation),
                "File" => Ok(EntityKind::File),
                "Folder" => Ok(EntityKind::Folder),
                "Layer" => Ok(EntityKind::Layer),
                "Group" => Ok(EntityKind::Group),
                "Author" => Ok(EntityKind::Author),
                "Concept" => Ok(EntityKind::Concept),
                "Tag" => Ok(EntityKind::Tag),
                "Prop" => Ok(EntityKind::Prop),
                "Attribute" => Ok(EntityKind::Attribute),
                "Quality" => Ok(EntityKind::Quality),
                "Stat" => Ok(EntityKind::Stat),
                "Benchmark" => Ok(EntityKind::Benchmark),
                "Family" => Ok(EntityKind::Family),
                "Location" => Ok(EntityKind::Location),
                _ => Err(SetError::InvalidValue(format!("unknown entity kind '{s}'"))),
            }
        }

        fn find_design_id_for_connection(kit: &KitGraphRef, connection_id: &str) -> std::result::Result<Id, SetError> {
            let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
            let cid = Id::from(connection_id);
            for d in &g.designs {
                if let Ok(dr) = d.read() {
                    if dr.connections.iter().any(|c| c.read().map(|r| r.id == cid).unwrap_or(false)) {
                        return Ok(dr.id.clone());
                    }
                }
            }
            Err(SetError::NotFound(format!("connection {connection_id}")))
        }

        fn piece_diff_to_change_commands(d: &crate::diff::PieceDiff) -> std::result::Result<Vec<crate::change_command::ChangePieceCommand>, SetError> {
            use crate::change_command::ChangePieceCommand;
            if d.props.as_ref().is_some_and(|p| !p.is_empty()) || d.attributes.as_ref().is_some_and(|a| !a.is_empty()) {
                return Err(SetError::InvalidValue("piece __patch: nested props/attributes not supported here; use dedicated commands".into()));
            }
            let mut out = Vec::new();
            if let Some(v) = &d.name {
                out.push(ChangePieceCommand::Name { name: v.clone() });
            }
            if let Some(v) = &d.description {
                out.push(ChangePieceCommand::Description { description: v.clone() });
            }
            if let Some(v) = &d.plane {
                out.push(ChangePieceCommand::Plane { plane: v.clone() });
            }
            if let Some(v) = &d.center {
                out.push(ChangePieceCommand::Center { center: v.clone() });
            }
            if let Some(v) = &d.scale {
                out.push(ChangePieceCommand::Scale { scale: v.clone() });
            }
            if let Some(v) = &d.mirror_plane {
                out.push(ChangePieceCommand::MirrorPlane { mirror_plane: v.clone() });
            }
            if let Some(v) = &d.hidden {
                out.push(ChangePieceCommand::Hidden { hidden: v.clone() });
            }
            if let Some(v) = &d.locked {
                out.push(ChangePieceCommand::Locked { locked: v.clone() });
            }
            if let Some(v) = &d.color {
                out.push(ChangePieceCommand::Color { color: v.clone() });
            }
            if let Some(v) = &d.r#type {
                out.push(ChangePieceCommand::Type { type_id: v.clone() });
            }
            if d.design.is_some() {
                return Err(SetError::InvalidValue("piece __patch: design field is not supported via setField; use a dedicated move command".into()));
            }
            Ok(out)
        }

        fn connection_diff_to_change_commands(d: &crate::diff::ConnectionDiff) -> std::result::Result<Vec<crate::change_command::ChangeConnectionCommand>, SetError> {
            use crate::change_command::ChangeConnectionCommand;
            if d.attributes.as_ref().is_some_and(|a| !a.is_empty()) {
                return Err(SetError::InvalidValue("connection __patch: nested attributes not supported here".into()));
            }
            let mut out = Vec::new();
            if let Some(v) = &d.gap {
                out.push(ChangeConnectionCommand::Gap { value: v.clone() });
            }
            if let Some(v) = &d.shift {
                out.push(ChangeConnectionCommand::Shift { value: v.clone() });
            }
            if let Some(v) = &d.rise {
                out.push(ChangeConnectionCommand::Rise { value: v.clone() });
            }
            if let Some(v) = &d.rotation {
                out.push(ChangeConnectionCommand::Rotation { value: v.clone() });
            }
            if let Some(v) = &d.turn {
                out.push(ChangeConnectionCommand::Turn { value: v.clone() });
            }
            if let Some(v) = &d.tilt {
                out.push(ChangeConnectionCommand::Tilt { value: v.clone() });
            }
            if let Some(v) = &d.x {
                out.push(ChangeConnectionCommand::X { value: v.clone() });
            }
            if let Some(v) = &d.y {
                out.push(ChangeConnectionCommand::Y { value: v.clone() });
            }
            if let Some(v) = &d.description {
                out.push(ChangeConnectionCommand::Description { value: v.clone() });
            }
            if let Some(s) = &d.connected {
                out.push(ChangeConnectionCommand::ReplaceConnected { side: s.clone() });
            }
            if let Some(s) = &d.connecting {
                out.push(ChangeConnectionCommand::ReplaceConnecting { side: s.clone() });
            }
            Ok(out)
        }

        pub fn change_kit_commands_for_field_patch(kit: &KitGraphRef, entity_kind: EntityKind, id: &str, field: &str, value: serde_json::Value) -> std::result::Result<Vec<crate::change_command::ChangeKitCommand>, SetError> {
            let id = id.to_string();
            let field = field.to_string();
            use crate::author::AuthorIdDto;
            use crate::change_command::{
                ChangeAuthorCommand, ChangeConceptCommand, ChangeDesignCommand, ChangeFamilyCommand, ChangeFileCommand, ChangeFolderCommand, ChangeKitCommand, ChangeKitQualityCommand, ChangePieceCommand, ChangePortCommand, ChangeTagCommand,
                ChangeTypeCommand,
            };
            use crate::concept::ConceptIdDto;
            use crate::connection::ConnectionIdDto;
            use crate::design::DesignIdDto;
            use crate::family::FamilyIdDto;
            use crate::file::FileIdDto;
            use crate::folder::FolderIdDto;
            use crate::piece::PieceIdDto;
            use crate::port::PortIdDto;
            use crate::quality::QualityIdDto;
            use crate::tag::TagIdDto;
            use crate::typ::TypeIdDto;
            Ok(match entity_kind {
                EntityKind::Kit => {
                    let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                    if g.id.as_str() != id {
                        return Err(SetError::NotFound(format!("kit {id}")));
                    }
                    drop(g);
                    vec![match field.as_str() {
                        "name" => {
                            let s: String = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitCommand::Name { name: s }
                        }
                        "description" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitCommand::Description { description: v }
                        }
                        "icon" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitCommand::Icon { icon: v }
                        }
                        "image" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitCommand::Image { image: v }
                        }
                        "preview" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitCommand::Preview { preview: v }
                        }
                        "remote" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitCommand::Remote { remote: v }
                        }
                        "homepage" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitCommand::Homepage { homepage: v }
                        }
                        "license" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitCommand::License { license: v }
                        }
                        "uri" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitCommand::Uri { uri: v }
                        }
                        "created" | "createdAt" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitCommand::Created { created: v }
                        }
                        "updated" | "updatedAt" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitCommand::Updated { updated: v }
                        }
                        "version" | "release" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitCommand::Version { version: v }
                        }
                        _ => return Err(SetError::InvalidValue(format!("unknown kit field '{field}'"))),
                    }]
                }
                EntityKind::Design => {
                    let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                    if g.design(id.as_str()).is_none() {
                        return Err(SetError::NotFound(format!("design {id}")));
                    }
                    drop(g);
                    let cmd = match field.as_str() {
                        "name" => {
                            let s: String = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeDesignCommand::Name { name: s }
                        }
                        "description" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeDesignCommand::Description { description: v }
                        }
                        "icon" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeDesignCommand::Icon { icon: v }
                        }
                        "image" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeDesignCommand::Image { image: v }
                        }
                        "unit" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeDesignCommand::Unit { unit: v }
                        }
                        _ => return Err(SetError::InvalidValue(format!("unknown design field '{field}'"))),
                    };
                    vec![ChangeKitCommand::ChangeDesignCommands { design_id: DesignIdDto { id: Id::from(id.as_str()) }, commands: vec![cmd] }]
                }
                EntityKind::Type => {
                    let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                    if g.semio_type(id.as_str()).is_none() {
                        return Err(SetError::NotFound(format!("type {id}")));
                    }
                    drop(g);
                    let cmd = match field.as_str() {
                        "name" => {
                            let s: String = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeTypeCommand::Name { name: s }
                        }
                        "description" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeTypeCommand::Description { description: v }
                        }
                        "icon" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeTypeCommand::Icon { icon: v }
                        }
                        "image" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeTypeCommand::Image { image: v }
                        }
                        "stock" => {
                            let v: Option<i64> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeTypeCommand::Stock { stock: v }
                        }
                        "virtual" | "typeVirtual" | "isAbstract" => {
                            let v: Option<bool> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeTypeCommand::TypeVirtual { value: v }
                        }
                        "unit" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeTypeCommand::Unit { unit: v }
                        }
                        _ => return Err(SetError::InvalidValue(format!("unknown type field '{field}'"))),
                    };
                    vec![ChangeKitCommand::ChangeTypeCommands { type_id: TypeIdDto { id: Id::from(id.as_str()) }, commands: vec![cmd] }]
                }
                EntityKind::Piece => {
                    let design_id = {
                        let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                        let mut found: Option<Id> = None;
                        for d in &g.designs {
                            if let Ok(dr) = d.read() {
                                if dr.piece(id.as_str()).is_some() {
                                    found = Some(dr.id.clone());
                                    break;
                                }
                            }
                        }
                        found.ok_or_else(|| SetError::NotFound(format!("piece {id}")))?
                    };
                    if field.as_str() == "__patch" {
                        let pd: crate::diff::PieceDiff = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                        if pd.is_empty() {
                            return Ok(vec![]);
                        }
                        let pcmds = Self::piece_diff_to_change_commands(&pd)?;
                        return Ok(vec![ChangeKitCommand::ChangeDesignCommands {
                            design_id: DesignIdDto { id: design_id },
                            commands: vec![ChangeDesignCommand::ChangePieceCommands { piece_id: PieceIdDto { id: Id::from(id.as_str()) }, commands: pcmds }],
                        }]);
                    }
                    let piece_cmd = match field.as_str() {
                        "name" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangePieceCommand::Name { name: v }
                        }
                        "color" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangePieceCommand::Color { color: v }
                        }
                        _ => return Err(SetError::InvalidValue(format!("unknown piece field '{field}'"))),
                    };
                    vec![ChangeKitCommand::ChangeDesignCommands { design_id: DesignIdDto { id: design_id }, commands: vec![ChangeDesignCommand::ChangePieceCommands { piece_id: PieceIdDto { id: Id::from(id.as_str()) }, commands: vec![piece_cmd] }] }]
                }
                EntityKind::Connection => {
                    let design_id = Self::find_design_id_for_connection(kit, &id)?;
                    if field.as_str() == "__patch" {
                        let cd: crate::diff::ConnectionDiff = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                        if cd.is_empty() {
                            return Ok(vec![]);
                        }
                        let ccmds = Self::connection_diff_to_change_commands(&cd)?;
                        return Ok(vec![ChangeKitCommand::ChangeDesignCommands {
                            design_id: DesignIdDto { id: design_id },
                            commands: vec![ChangeDesignCommand::ChangeConnectionCommands { connection_id: ConnectionIdDto { id: Id::from(id.as_str()) }, commands: ccmds }],
                        }]);
                    }
                    return Err(SetError::InvalidValue(format!("unknown connection field '{field}' (use __patch for batch)")));
                }
                EntityKind::Author => {
                    let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                    if !g.authors.iter().any(|a| a.read().map(|r| r.id.as_str() == id.as_str()).unwrap_or(false)) {
                        return Err(SetError::NotFound(format!("author {id}")));
                    }
                    drop(g);
                    let cmd = match field.as_str() {
                        "name" => {
                            let s: String = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeAuthorCommand::Name { name: s }
                        }
                        "email" => {
                            let s: String = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeAuthorCommand::Email { email: s }
                        }
                        "role" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeAuthorCommand::Role { role: v }
                        }
                        "rank" => {
                            let v: Option<i64> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeAuthorCommand::Rank { rank: v }
                        }
                        _ => return Err(SetError::InvalidValue(format!("unknown author field '{field}'"))),
                    };
                    vec![ChangeKitCommand::ChangeAuthorCommands { author_id: AuthorIdDto { id: Id::from(id.as_str()) }, commands: vec![cmd] }]
                }
                EntityKind::Concept => {
                    let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                    if !g.concepts.iter().any(|c| c.read().map(|r| r.id.as_str() == id.as_str()).unwrap_or(false)) {
                        return Err(SetError::NotFound(format!("concept {id}")));
                    }
                    drop(g);
                    let cmd = match field.as_str() {
                        "name" => {
                            let s: String = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeConceptCommand::Name { name: s }
                        }
                        "description" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeConceptCommand::Description { description: v }
                        }
                        "order" | "orderIndex" => {
                            let v: Option<i64> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeConceptCommand::Order { order: v }
                        }
                        _ => return Err(SetError::InvalidValue(format!("unknown concept field '{field}'"))),
                    };
                    vec![ChangeKitCommand::ChangeConceptCommands { concept_id: ConceptIdDto { id: Id::from(id.as_str()) }, commands: vec![cmd] }]
                }
                EntityKind::Tag => {
                    let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                    if !g.tags.iter().any(|t| t.read().map(|r| r.id.as_str() == id.as_str()).unwrap_or(false)) {
                        return Err(SetError::NotFound(format!("tag {id}")));
                    }
                    drop(g);
                    let cmd = match field.as_str() {
                        "name" => {
                            let s: String = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeTagCommand::Name { name: s }
                        }
                        "order" | "orderIndex" => {
                            let v: Option<i64> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeTagCommand::Order { order: v }
                        }
                        _ => return Err(SetError::InvalidValue(format!("unknown tag field '{field}'"))),
                    };
                    vec![ChangeKitCommand::ChangeTagCommands { tag_id: TagIdDto { id: Id::from(id.as_str()) }, commands: vec![cmd] }]
                }
                EntityKind::File => {
                    let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                    if !g.files.iter().any(|f| f.read().map(|r| r.id.as_str() == id.as_str()).unwrap_or(false)) {
                        return Err(SetError::NotFound(format!("file {id}")));
                    }
                    drop(g);
                    let cmd = match field.as_str() {
                        "url" => {
                            let s: String = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeFileCommand::Url { url: s }
                        }
                        "mime" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeFileCommand::Mime { mime: v }
                        }
                        "size" => {
                            let v: Option<i64> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeFileCommand::Size { size: v }
                        }
                        "hash" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeFileCommand::Hash { hash: v }
                        }
                        "description" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeFileCommand::Description { description: v }
                        }
                        "created" | "createdAt" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeFileCommand::Created { created: v }
                        }
                        "updated" | "updatedAt" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeFileCommand::Updated { updated: v }
                        }
                        _ => return Err(SetError::InvalidValue(format!("unknown file field '{field}'"))),
                    };
                    vec![ChangeKitCommand::ChangeFileCommands { file_id: FileIdDto { id: Id::from(id.as_str()) }, commands: vec![cmd] }]
                }
                EntityKind::Folder => {
                    let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                    if !g.folders.iter().any(|f| f.read().map(|r| r.id.as_str() == id.as_str()).unwrap_or(false)) {
                        return Err(SetError::NotFound(format!("folder {id}")));
                    }
                    drop(g);
                    let cmd = match field.as_str() {
                        "path" => {
                            let s: String = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeFolderCommand::Path { path: s }
                        }
                        "description" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeFolderCommand::Description { description: v }
                        }
                        _ => return Err(SetError::InvalidValue(format!("unknown folder field '{field}'"))),
                    };
                    vec![ChangeKitCommand::ChangeFolderCommands { folder_id: FolderIdDto { id: Id::from(id.as_str()) }, commands: vec![cmd] }]
                }
                EntityKind::Quality => {
                    let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                    if !g.qualities.iter().any(|q| q.read().map(|r| r.id.as_str() == id.as_str()).unwrap_or(false)) {
                        return Err(SetError::NotFound(format!("quality {id}")));
                    }
                    drop(g);
                    let cmd = match field.as_str() {
                        "key" => {
                            let s: String = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitQualityCommand::Key { key: s }
                        }
                        "value" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitQualityCommand::Value { value: v }
                        }
                        "unit" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitQualityCommand::Unit { unit: v }
                        }
                        "definition" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitQualityCommand::Definition { definition: v }
                        }
                        "description" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeKitQualityCommand::Description { description: v }
                        }
                        _ => return Err(SetError::InvalidValue(format!("unknown quality field '{field}'"))),
                    };
                    vec![ChangeKitCommand::ChangeKitQualityCommands { quality_id: QualityIdDto { id: Id::from(id.as_str()) }, commands: vec![cmd] }]
                }
                EntityKind::Family => {
                    let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                    if !g.families.iter().any(|f| f.read().map(|r| r.id.as_str() == id.as_str()).unwrap_or(false)) {
                        return Err(SetError::NotFound(format!("family {id}")));
                    }
                    drop(g);
                    let cmd = match field.as_str() {
                        "name" => {
                            let s: String = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeFamilyCommand::Name { name: s }
                        }
                        "description" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeFamilyCommand::Description { description: v }
                        }
                        "icon" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangeFamilyCommand::Icon { icon: v }
                        }
                        _ => return Err(SetError::InvalidValue(format!("unknown family field '{field}'"))),
                    };
                    vec![ChangeKitCommand::ChangeFamilyCommands { family_id: FamilyIdDto { id: Id::from(id.as_str()) }, commands: vec![cmd] }]
                }
                EntityKind::Port => {
                    let pref = {
                        let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                        g.port_by_id(&Id::from(id.as_str())).ok_or_else(|| SetError::NotFound(format!("port {id}")))?
                    };
                    let parent_fam_id: Option<Id> = match pref.read().map_err(|_| SetError::LockPoisoned("port".into()))?.parent_family.upgrade() {
                        Some(pf) => Some(pf.read().map_err(|_| SetError::LockPoisoned("family".into()))?.id.clone()),
                        None => None,
                    };
                    let pcmd = match field.as_str() {
                        "name" => {
                            let s: String = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangePortCommand::Name { name: s }
                        }
                        "description" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangePortCommand::Description { description: v }
                        }
                        "icon" => {
                            let v: Option<String> = serde_json::from_value(value).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                            ChangePortCommand::Icon { icon: v }
                        }
                        _ => return Err(SetError::InvalidValue(format!("unknown port field '{field}'"))),
                    };
                    let pid = Id::from(id.as_str());
                    if let Some(fid) = parent_fam_id {
                        vec![ChangeKitCommand::ChangeFamilyCommands { family_id: FamilyIdDto { id: fid }, commands: vec![ChangeFamilyCommand::ChangePortCommands { port_id: PortIdDto { id: pid }, commands: vec![pcmd] }] }]
                    } else {
                        vec![ChangeKitCommand::ChangeKitPortCommands { port_id: PortIdDto { id: pid }, commands: vec![pcmd] }]
                    }
                }
                _ => return Err(SetError::InvalidValue(format!("change_kit_commands_for_field_patch not implemented for {entity_kind:?}"))),
            })
        }

        pub fn set_field_rpc(kit: &KitGraphRef, entity_kind: EntityKind, id: &str, field: &str, value: serde_json::Value) -> SetResult {
            let cmds = Self::change_kit_commands_for_field_patch(kit, entity_kind, id, field, value)?;
            Self::control_plane_batch_apply_with_undo(kit, &cmds).map(|_| ())
        }

        pub fn get_field_rpc(kit: &KitGraphRef, entity_kind: EntityKind, id: &str, field: &str) -> std::result::Result<serde_json::Value, SetError> {
            let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
            match entity_kind {
                EntityKind::Kit => {
                    if g.id.as_str() != id {
                        return Err(SetError::NotFound(format!("kit {id}")));
                    }
                    match field {
                        "name" => Ok(serde_json::json!(g.name)),
                        "description" => Ok(serde_json::to_value(&g.description).unwrap()),
                        "icon" => Ok(serde_json::to_value(&g.icon).unwrap()),
                        "image" => Ok(serde_json::to_value(&g.image).unwrap()),
                        "preview" => Ok(serde_json::to_value(&g.preview).unwrap()),
                        "remote" => Ok(serde_json::to_value(&g.remote).unwrap()),
                        "homepage" => Ok(serde_json::to_value(&g.homepage).unwrap()),
                        "license" => Ok(serde_json::to_value(&g.license).unwrap()),
                        "uri" => Ok(serde_json::to_value(&g.uri).unwrap()),
                        "created" | "createdAt" => Ok(serde_json::to_value(&g.created).unwrap()),
                        "updated" | "updatedAt" => Ok(serde_json::to_value(&g.updated).unwrap()),
                        "version" | "release" => Ok(serde_json::to_value(&g.version).unwrap()),
                        _ => Err(SetError::InvalidValue(format!("unknown kit field '{field}'"))),
                    }
                }
                EntityKind::Piece => {
                    for d in &g.designs {
                        if let Ok(dr) = d.read() {
                            if let Some(p) = dr.piece(id) {
                                if let Ok(pr) = p.read() {
                                    return match field {
                                        "name" => Ok(serde_json::to_value(&pr.name).unwrap()),
                                        "color" => Ok(serde_json::to_value(&pr.color).unwrap()),
                                        _ => Err(SetError::InvalidValue(format!("unknown piece field '{field}'"))),
                                    };
                                }
                            }
                        }
                    }
                    Err(SetError::NotFound(format!("piece {id}")))
                }
                EntityKind::Design => {
                    let d = g.design(id).ok_or_else(|| SetError::NotFound(format!("design {id}")))?;
                    let dr = d.read().map_err(|_| SetError::LockPoisoned("design".into()))?;
                    match field {
                        "name" => Ok(serde_json::json!(dr.name)),
                        _ => Err(SetError::InvalidValue(format!("unknown design field '{field}'"))),
                    }
                }
                EntityKind::Type => {
                    let t = g.semio_type(id).ok_or_else(|| SetError::NotFound(format!("type {id}")))?;
                    let tr = t.read().map_err(|_| SetError::LockPoisoned("type".into()))?;
                    match field {
                        "name" => Ok(serde_json::json!(tr.name)),
                        _ => Err(SetError::InvalidValue(format!("unknown type field '{field}'"))),
                    }
                }
                _ => Err(SetError::InvalidValue(format!("get_field_rpc not implemented for {entity_kind:?}"))),
            }
        }

        pub fn map_semio_err(e: SemioError) -> SetError {
            match e {
                SemioError::NotFound { kind, id } => SetError::NotFound(format!("{} {}", kind, id.as_str())),
                SemioError::LockPoisoned(s) => SetError::LockPoisoned(s.to_string()),
                SemioError::InvalidOperation(m) => SetError::Internal(m),
                SemioError::Json(j) => SetError::InvalidValue(j.to_string()),
                SemioError::Io(i) => SetError::Internal(i.to_string()),
                SemioError::Other(o) => SetError::Internal(o),
                #[cfg(not(target_arch = "wasm32"))]
                SemioError::Sqlite(s) => SetError::Internal(s.to_string()),
                #[cfg(not(target_arch = "wasm32"))]
                SemioError::Zip(z) => SetError::Internal(z.to_string()),
            }
        }

        pub fn apply_kit_state(kit: &KitGraphRef, after: KitFullDto) -> SetResult {
            Self::replace_from_full_dto(kit, after)
        }

        pub fn apply_kit_diff(kit: &KitGraphRef, diff: &crate::kit_diff::KitDiff) -> std::result::Result<crate::kit_diff::KitDiff, SetError> {
            if diff.is_empty() {
                return Ok(crate::kit_diff::KitDiff::default());
            }
            let b0 = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?.to_full_dto();
            let mut a = b0.clone();
            diff.merge_into_baseline_dto(&mut a);
            if b0 != a {
                Self::apply_kit_state(kit, a.clone())?;
                crate::event_wire::emit_kit_dto_reconcile_events(kit, &b0, &a);
            }
            Ok(crate::kit_diff::KitDiff::between(&b0, &a))
        }

        pub fn replace_from_full_dto(kit: &KitGraphRef, d: KitFullDto) -> SetResult {
            let new_arc = Self::from_full_dto(d);
            let mut merged = match Arc::try_unwrap(new_arc) {
                Ok(rw) => match rw.into_inner() {
                    Ok(s) => s,
                    Err(_) => return Err(SetError::LockPoisoned("kit".into())),
                },
                Err(_) => {
                    return Err(SetError::Internal("replace_from_full_dto: expected single owner of new kit".into()));
                }
            };
            let bus = {
                let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                g.event_bus.clone()
            };
            merged.event_bus = bus;
            {
                let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                let preserve = (g.undo_past.clone(), g.undo_future.clone(), g.undo_inhibit, g.initial.clone(), g.checkpoints.clone(), g.alternatives.clone(), g.the_kit_head.clone(), g.the_kit_draft.clone(), g.children.clone());
                *g = merged;
                g.undo_past = preserve.0;
                g.undo_future = preserve.1;
                g.undo_inhibit = preserve.2;
                g.initial = preserve.3;
                g.checkpoints = preserve.4;
                g.alternatives = preserve.5;
                g.the_kit_head = preserve.6;
                g.the_kit_draft = preserve.7;
                g.children = preserve.8;
            }
            event_wire::rewire_parent_kits(kit);
            event_wire::wire_graph_bus(kit);
            {
                let g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                g.invalidate_hash();
                g.invalidate_validation();
            }
            Ok(())
        }

        ///
        pub fn execute(kit: &KitGraphRef, cmd: crate::kit_store_command::KitStoreCommand) -> crate::error::Result<crate::kit_store_command::KitStoreCommandResult> {
            cmd.execute(kit)
        }

        pub fn with_undo<F>(kit: &KitGraphRef, f: F) -> SetResult
        where
            F: FnOnce() -> SetResult,
        {
            let skip = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?.undo_inhibit > 0;
            if skip {
                return f();
            }
            let before = serde_json::to_value(kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?.to_full_dto()).map_err(|e| SetError::Internal(format!("undo snapshot: {e}")))?;
            f()?;
            let after = serde_json::to_value(kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?.to_full_dto()).map_err(|e| SetError::Internal(format!("undo snapshot: {e}")))?;
            if before == after {
                return Ok(());
            }
            let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
            g.undo_past.push(UndoStep { before, after });
            if g.undo_past.len() > Self::MAX_UNDO_STEPS {
                g.undo_past.remove(0);
            }
            g.undo_future.clear();
            Ok(())
        }

        pub(crate) fn emit_kit_change_event_bus(kit: &KitGraphRef, change: &crate::kit_change::KitChange) {
            if let Ok(g) = kit.read() {
                g.event_bus.emit(crate::events::kit_event_from_kit_change(change));
            }
        }

        pub(crate) fn control_plane_pre_batch(kit: &KitGraphRef, commands: &[ChangeKitCommand]) -> std::result::Result<ControlPlanePre, SetError> {
            use crate::kit_change::KitChange;
            let kind = ChangeKitCommand::batch_kind(commands);
            if commands.is_empty() {
                return Ok(ControlPlanePre { kc: None, kind, inverse_flat: Vec::new() });
            }
            let kc = KitChange::lift_flat(kit, commands.to_vec(), kind.clone(), None, None).map_err(Self::map_semio_err)?;
            let inverse_flat = kc.flatten_inverse_commands();
            Ok(ControlPlanePre { kc: Some(kc), kind, inverse_flat })
        }

        pub(crate) fn control_plane_batch_apply_with_undo(kit: &KitGraphRef, commands: &[ChangeKitCommand]) -> std::result::Result<ControlPlanePre, SetError> {
            let pre = Self::control_plane_pre_batch(kit, commands)?;
            Self::with_undo(kit, || {
                if commands.is_empty() {
                    return Ok(());
                }
                let _ = ChangeKitCommand::apply_many(kit, commands).map_err(Self::map_semio_err)?;
                Ok(())
            })?;
            if let Some(ref kc) = pre.kc {
                Self::emit_kit_change_event_bus(kit, kc);
            }
            Ok(pre)
        }

        pub(crate) fn open_transaction_apply_one_command(kit: &KitGraphRef, alternative_id: Option<&Id>, draft_id: &Id, transaction_id: &Id, c: &ChangeKitCommand) -> std::result::Result<bool, SemioError> {
            use crate::kit_change::KitChange;
            let before = {
                let g = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                g.to_full_dto()
            };
            let kind = ChangeKitCommand::declared_kind(c);
            let kc = KitChange::lift_flat(kit, vec![c.clone()], kind, None, None).map_err(|e| SemioError::InvalidOperation(format!("lift kit change: {e}")))?;
            c.apply(kit).map_err(|e| SemioError::InvalidOperation(e.to_string()))?;
            let after = {
                let g = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
                g.to_full_dto()
            };
            if before == after {
                return Ok(false);
            }
            let mut recorded = false;
            {
                let mut g = kit.write().map_err(|_| SemioError::LockPoisoned("kit"))?;
                if let Some(tx) = g.draft_mut_for_owner(alternative_id, draft_id).and_then(|d| d.open_transaction_mut(transaction_id)) {
                    tx.record(kc.clone());
                    recorded = true;
                }
            }
            Self::emit_kit_change_event_bus(kit, &kc);
            Ok(recorded)
        }

        pub fn undo(kit: &KitGraphRef) -> SetResult {
            let step = {
                let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                g.undo_past.pop()
            };
            let Some(step) = step else {
                return Err(SetError::Internal("nothing to undo".into()));
            };
            let before: KitFullDto = serde_json::from_value(step.before.clone()).map_err(|e| SetError::Internal(format!("undo: {e}")))?;
            {
                let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                g.undo_inhibit += 1;
            }
            let r = Self::replace_from_full_dto(kit, before);
            {
                let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                g.undo_inhibit = g.undo_inhibit.saturating_sub(1);
            }
            match r {
                Ok(()) => {
                    let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                    g.undo_future.push(step);
                    Ok(())
                }
                Err(e) => {
                    let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                    g.undo_past.push(step);
                    Err(e)
                }
            }
        }

        pub fn redo(kit: &KitGraphRef) -> SetResult {
            let step = {
                let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                g.undo_future.pop()
            };
            let Some(step) = step else {
                return Err(SetError::Internal("nothing to redo".into()));
            };
            let after: KitFullDto = serde_json::from_value(step.after.clone()).map_err(|e| SetError::Internal(format!("redo: {e}")))?;
            {
                let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                g.undo_inhibit += 1;
            }
            let r = Self::replace_from_full_dto(kit, after);
            {
                let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                g.undo_inhibit = g.undo_inhibit.saturating_sub(1);
            }
            match r {
                Ok(()) => {
                    let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                    g.undo_past.push(step);
                    Ok(())
                }
                Err(e) => {
                    let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                    g.undo_future.push(step);
                    Err(e)
                }
            }
        }

        pub fn can_undo(kit: &KitGraphRef) -> bool {
            kit.read().map(|g| !g.undo_past.is_empty()).unwrap_or(false)
        }

        pub fn can_redo(kit: &KitGraphRef) -> bool {
            kit.read().map(|g| !g.undo_future.is_empty()).unwrap_or(false)
        }

        pub fn change_kit_commands_for_add_child(kit: &KitGraphRef, parent_kind: EntityKind, parent_id: &str, child_kind: EntityKind, dto: serde_json::Value) -> std::result::Result<Vec<crate::change_command::ChangeKitCommand>, SetError> {
            use crate::change_command::{ChangeDesignCommand, ChangeKitCommand};
            use crate::design::DesignIdDto;
            use crate::family::FamilyFullDto;
            let pg = parent_id.to_string();
            match (parent_kind, child_kind) {
                (EntityKind::Kit, EntityKind::Family) => {
                    let kid = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?.id.as_str().to_string();
                    if pg != kid {
                        return Err(SetError::NotFound(format!("kit {pg}")));
                    }
                    let family: FamilyFullDto = serde_json::from_value(dto).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                    Ok(vec![ChangeKitCommand::AddFamily { family }])
                }
                (EntityKind::Design, EntityKind::Piece) => {
                    let piece: PieceFullDto = serde_json::from_value(dto).map_err(|e| SetError::InvalidValue(e.to_string()))?;
                    Ok(vec![ChangeKitCommand::ChangeDesignCommands { design_id: DesignIdDto { id: Id::from(pg.as_str()) }, commands: vec![ChangeDesignCommand::AddPiece { piece }] }])
                }
                _ => Err(SetError::InvalidValue(format!("change_kit_commands_for_add_child not implemented for {parent_kind:?} -> {child_kind:?}"))),
            }
        }

        pub fn change_kit_commands_for_remove_child(kit: &KitGraphRef, parent_kind: EntityKind, parent_id: &str, child_kind: EntityKind, child_id: &str) -> std::result::Result<Vec<crate::change_command::ChangeKitCommand>, SetError> {
            use crate::change_command::{ChangeDesignCommand, ChangeKitCommand};
            use crate::design::DesignIdDto;
            use crate::family::FamilyIdDto;
            use crate::piece::PieceIdDto;
            let pg = parent_id.to_string();
            let cg = child_id.to_string();
            match (parent_kind, child_kind) {
                (EntityKind::Kit, EntityKind::Family) => {
                    let kid = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?.id.as_str().to_string();
                    if pg != kid {
                        return Err(SetError::NotFound(format!("kit {pg}")));
                    }
                    Ok(vec![ChangeKitCommand::RemoveFamily { family_id: FamilyIdDto { id: Id::from(cg.as_str()) } }])
                }
                (EntityKind::Design, EntityKind::Piece) => {
                    Ok(vec![ChangeKitCommand::ChangeDesignCommands { design_id: DesignIdDto { id: Id::from(pg.as_str()) }, commands: vec![ChangeDesignCommand::RemovePiece { piece_id: PieceIdDto { id: Id::from(cg.as_str()) } }] }])
                }
                _ => Err(SetError::InvalidValue(format!("change_kit_commands_for_remove_child not implemented for {parent_kind:?} -> {child_kind:?}"))),
            }
        }

        pub fn add_child_rpc(kit: &KitGraphRef, parent_kind: EntityKind, parent_id: &str, child_kind: EntityKind, dto: serde_json::Value) -> SetResult {
            let cmds = Self::change_kit_commands_for_add_child(kit, parent_kind, parent_id, child_kind, dto)?;
            Self::control_plane_batch_apply_with_undo(kit, &cmds).map(|_| ())
        }

        pub fn remove_child_rpc(kit: &KitGraphRef, parent_kind: EntityKind, parent_id: &str, child_kind: EntityKind, child_id: &str) -> SetResult {
            let cmds = Self::change_kit_commands_for_remove_child(kit, parent_kind, parent_id, child_kind, child_id)?;
            Self::control_plane_batch_apply_with_undo(kit, &cmds).map(|_| ())
        }

        pub fn validate(&self) -> ValidationResult {
            self.validation_cache.get_or_init(|| self.compute_validation())
        }

        fn compute_validation(&self) -> ValidationResult {
            let mut result = ValidationResult::valid();
            if self.name.trim().is_empty() {
                result.is_valid = false;
                result.errors.push("kit.name must not be empty".into());
            }

            let mut ids: Vec<String> = Vec::new();
            ids.push(self.id.as_str().to_string());

            for p in &self.ports {
                if let Ok(p) = p.read() {
                    ids.push(p.id.as_str().to_string());
                }
            }
            for f in &self.families {
                if let Ok(f) = f.read() {
                    ids.push(f.id.as_str().to_string());
                    for p in &f.ports {
                        if let Ok(p) = p.read() {
                            ids.push(p.id.as_str().to_string());
                        }
                    }
                }
            }
            for loc in &self.locations {
                if let Ok(loc) = loc.read() {
                    ids.push(loc.id.as_str().to_string());
                }
            }

            for t in &self.types {
                if let Ok(t) = t.read() {
                    if t.name.trim().is_empty() {
                        result.is_valid = false;
                        result.errors.push(format!("type {} has empty name", t.id));
                    }
                    ids.push(t.id.as_str().to_string());
                    for c in &t.connectors {
                        if let Ok(c) = c.read() {
                            ids.push(c.id.as_str().to_string());
                        }
                    }
                    for r in &t.representations {
                        if let Ok(r) = r.read() {
                            if r.url.trim().is_empty() {
                                result.is_valid = false;
                                result.errors.push(format!("representation {} has empty url", r.id));
                            }
                            ids.push(r.id.as_str().to_string());
                        }
                    }
                }
            }

            for f in &self.files {
                if let Ok(f) = f.read() {
                    if f.url.trim().is_empty() {
                        result.is_valid = false;
                        result.errors.push(format!("file {} has empty url", f.id));
                    }
                    ids.push(f.id.as_str().to_string());
                }
            }

            for d in &self.designs {
                if let Ok(d) = d.read() {
                    if d.name.trim().is_empty() {
                        result.is_valid = false;
                        result.errors.push(format!("design {} has empty name", d.id));
                    }
                    ids.push(d.id.as_str().to_string());
                    for p in &d.pieces {
                        if let Ok(p) = p.read() {
                            if p.type_ref.as_ref().and_then(|t| t.upgrade()).is_none() {
                                result.is_valid = false;
                                result.errors.push(format!("piece {} has no valid type reference", p.id));
                            }
                            ids.push(p.id.as_str().to_string());
                        }
                    }
                    for c in &d.connections {
                        if let Ok(conn) = c.read() {
                            ids.push(conn.id.as_str().to_string());
                            if let Ok(s0) = conn.connected.read() {
                                if s0.piece.upgrade().is_none() {
                                    result.is_valid = false;
                                    result.errors.push(format!("connection {} connected side has no piece", conn.id));
                                }
                            }
                            if let Ok(s1) = conn.connecting.read() {
                                if s1.piece.upgrade().is_none() {
                                    result.is_valid = false;
                                    result.errors.push(format!("connection {} connecting side has no piece", conn.id));
                                }
                            }
                        }
                    }
                }
            }

            ids.sort();
            for w in ids.windows(2) {
                if w[0] == w[1] {
                    result.is_valid = false;
                    result.errors.push(format!("duplicate id: {}", w[0]));
                    break;
                }
            }

            for d in &self.designs {
                if let Ok(d) = d.read() {
                    if d.connections.len() > d.pieces.len() && !d.pieces.is_empty() {
                        result.is_valid = false;
                        result.warnings.push(format!("design {} has more connections than pieces (possible cycle or bad graph)", d.id));
                    }
                }
            }

            result
        }

        pub fn are_equal(&self, other: &KitGraph) -> bool {
            self.hash() == other.hash()
        }

