        pub fn port_by_id(&self, id: &Id) -> Option<PortStoreRef> {
            for p in &self.ports {
                if p.read().ok().map(|r| r.id == *id).unwrap_or(false) {
                    return Some(p.clone());
                }
            }
            for f in &self.families {
                if let Ok(fr) = f.read() {
                    for p in &fr.ports {
                        if p.read().ok().map(|r| r.id == *id).unwrap_or(false) {
                            return Some(p.clone());
                        }
                    }
                }
            }
            None
        }

        fn build_family_port_index(g: &KitGraph) -> (HashMap<Id, FamilyStoreRef>, HashMap<Id, PortStoreRef>) {
            let mut family_by_id: HashMap<Id, FamilyStoreRef> = HashMap::new();
            for f in &g.families {
                if let Ok(fr) = f.read() {
                    family_by_id.insert(fr.id.clone(), f.clone());
                }
            }
            let mut port_by_id: HashMap<Id, PortStoreRef> = HashMap::new();
            for p in &g.ports {
                if let Ok(pr) = p.read() {
                    port_by_id.insert(pr.id.clone(), p.clone());
                }
            }
            for f in &g.families {
                if let Ok(fr) = f.read() {
                    for p in &fr.ports {
                        if let Ok(pr) = p.read() {
                            port_by_id.insert(pr.id.clone(), p.clone());
                        }
                    }
                }
            }
            (family_by_id, port_by_id)
        }

        /// 🧮 Same 32-bit string hash magnitude as sketchpad `hashString` for union-find tie-breaks.
        pub(crate) fn js_string_hash_abs(text: &str) -> u32 {
            let mut h: i32 = 0;
            for c in text.chars() {
                h = (h << 5).wrapping_sub(h).wrapping_add(c as i32);
            }
            if h == i32::MIN { 2_147_483_648u32 } else { h.unsigned_abs() }
        }

        /// 🗺️ Union-find root for a port's compatibility component (matches sketchpad `createPortGroupMap` tie-break).
        pub(crate) fn port_compatibility_group_root_id(kit: &KitGraph, start: &Id) -> Option<Id> {
            use std::collections::HashMap;
            let (_, port_by_id) = Self::build_family_port_index(kit);
            if !port_by_id.contains_key(start) {
                return None;
            }
            let mut parent: HashMap<Id, Id> = port_by_id.keys().cloned().map(|k| (k.clone(), k)).collect();
            fn find(parent: &mut HashMap<Id, Id>, x: &Id) -> Id {
                let p = parent.get(x).cloned().unwrap_or_else(|| x.clone());
                if p == *x {
                    x.clone()
                } else {
                    let r = find(parent, &p);
                    parent.insert(x.clone(), r.clone());
                    r
                }
            }
            fn union(parent: &mut HashMap<Id, Id>, a: &Id, b: &Id) {
                let ra = find(parent, a);
                let rb = find(parent, b);
                if ra == rb {
                    return;
                }
                let ha = KitGraph::js_string_hash_abs(ra.as_str());
                let hb = KitGraph::js_string_hash_abs(rb.as_str());
                if ha <= hb {
                    parent.insert(rb, ra);
                } else {
                    parent.insert(ra, rb);
                }
            }
            for (pid, pref) in &port_by_id {
                if let Ok(pr) = pref.read() {
                    for w in &pr.compatible_ports {
                        if let Some(op) = w.upgrade() {
                            if let Ok(or) = op.read() {
                                let oid = or.id.clone();
                                if port_by_id.contains_key(&oid) {
                                    union(&mut parent, pid, &oid);
                                }
                            }
                        }
                    }
                }
            }
            Some(find(&mut parent, start))
        }

        fn domain_type_index(kit: &KitGraph) -> HashMap<Id, TypeStoreRef> {
            kit.types.iter().filter_map(|t| t.read().ok().map(|r| (r.id.clone(), t.clone()))).collect()
        }

        fn domain_family_index(kit: &KitGraph) -> HashMap<Id, FamilyStoreRef> {
            kit.families.iter().filter_map(|f| f.read().ok().map(|r| (r.id.clone(), f.clone()))).collect()
        }

        pub fn apply_type_diff_fragment(kit: &KitGraphRef, type_id: &Id, fragment: &crate::diff::TypeDiff) -> SetResult {
            if fragment.is_empty() {
                return Ok(());
            }
            let dto = {
                let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                let t = g.semio_type(type_id.as_str()).ok_or_else(|| SetError::NotFound(format!("type {}", type_id)))?;
                let dto = t.read().map_err(|_| SetError::LockPoisoned("type".into()))?.to_full_dto();
                dto
            };
            let mut dto = dto;
            crate::diff::merge_type_diff_into_full(&mut dto, fragment);
            if KitGraph::remove_type_dto(kit, type_id.as_str())?.is_none() {
                return Err(SetError::NotFound(format!("type {}", type_id)));
            }
            KitGraph::insert_type_dto(kit, dto)
        }

        pub fn insert_design_ref(kit: &KitGraphRef, dto: DesignFullDto) -> SetResult {
            let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
            if g.designs.iter().any(|d| d.read().map(|r| r.id.as_str() == dto.id.as_str()).unwrap_or(false)) {
                return Err(SetError::DuplicateId(format!("design {}", dto.id)));
            }
            let idx = Self::domain_type_index(&g);
            let family_by_id: HashMap<Id, FamilyStoreRef> = g.families.iter().filter_map(|f| f.read().ok().map(|r| (r.id.clone(), f.clone()))).collect();
            let design = DesignStore::hydrate_from_full_dto(dto, &idx, &family_by_id);
            {
                let kw = Arc::downgrade(kit);
                if let Ok(mut dw) = design.write() {
                    dw.parent_kit = kw;
                }
            }
            g.designs.push(design);
            g.invalidate_hash();
            g.invalidate_validation();
            drop(g);
            event_wire::wire_graph_bus(kit);
            Ok(())
        }

        pub fn insert_type_dto(kit: &KitGraphRef, dto: TypeFullDto) -> SetResult {
            let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
            if g.types.iter().any(|t| t.read().map(|r| r.id.as_str() == dto.id.as_str()).unwrap_or(false)) {
                return Err(SetError::DuplicateId(format!("type {}", dto.id)));
            }
            let (family_by_id, port_by_id) = Self::build_family_port_index(&g);
            let t = TypeStore::hydrate_from_full_dto(dto, kit, &g.files, &family_by_id, &port_by_id);
            g.types.push(t);
            g.invalidate_hash();
            g.invalidate_validation();
            drop(g);
            event_wire::wire_graph_bus(kit);
            Ok(())
        }

        pub fn remove_type_dto(kit: &KitGraphRef, type_id: &str) -> std::result::Result<Option<TypeFullDto>, SetError> {
            let pos = {
                let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                g.types.iter().position(|t| t.read().map(|r| r.id.as_str() == type_id).unwrap_or(false))
            };
            let Some(pos) = pos else {
                return Ok(None);
            };
            let t = { kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?.types.remove(pos) };
            if let Ok(tr) = t.read() {
                let dto = tr.to_full_dto();
                {
                    let g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                    g.invalidate_hash();
                    g.invalidate_validation();
                }
                event_wire::wire_graph_bus(kit);
                return Ok(Some(dto));
            }
            Ok(None)
        }

        fn check_port_unused_by_connectors(g: &KitGraph, pid: &Id) -> std::result::Result<(), SetError> {
            for t in &g.types {
                let tr = t.read().map_err(|_| SetError::LockPoisoned("type".into()))?;
                if tr.connector_for_port_id(pid).is_some() {
                    return Err(SetError::InvalidValue(format!("port {} is still referenced by a connector on type {}", pid.as_str(), tr.id.as_str())));
                }
            }
            Ok(())
        }

        fn assert_family_removable(g: &KitGraph, fid: &Id) -> std::result::Result<(), SetError> {
            for t in &g.types {
                let tr = t.read().map_err(|_| SetError::LockPoisoned("type".into()))?;
                for w in &tr.families {
                    if let Some(fr) = w.upgrade() {
                        if let Ok(r) = fr.read() {
                            if r.id == *fid {
                                return Err(SetError::InvalidValue(format!("family {} is still referenced by type {}", fid.as_str(), tr.id.as_str())));
                            }
                        }
                    }
                }
            }
            for d in &g.designs {
                let dr = d.read().map_err(|_| SetError::LockPoisoned("design".into()))?;
                for w in &dr.families {
                    if let Some(fr) = w.upgrade() {
                        if let Ok(r) = fr.read() {
                            if r.id == *fid {
                                return Err(SetError::InvalidValue(format!("family {} is still referenced by design {}", fid.as_str(), dr.id.as_str())));
                            }
                        }
                    }
                }
            }
            let Some(fam) = g.families.iter().find(|f| f.read().map(|r| r.id == *fid).unwrap_or(false)) else {
                return Ok(());
            };
            let port_ids: Vec<Id> = fam.read().map_err(|_| SetError::LockPoisoned("family".into()))?.ports.iter().filter_map(|p| p.read().ok().map(|r| r.id.clone())).collect();
            for pid in &port_ids {
                Self::check_port_unused_by_connectors(g, pid)?;
            }
            Ok(())
        }

        pub fn insert_family_dto(kit: &KitGraphRef, dto: FamilyFullDto) -> SetResult {
            let mut g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
            if g.families.iter().any(|f| f.read().map(|r| r.id == dto.id).unwrap_or(false)) {
                return Err(SetError::DuplicateId(format!("family {}", dto.id)));
            }
            for pd in &dto.ports {
                if g.port_by_id(&pd.id).is_some() {
                    return Err(SetError::DuplicateId(format!("port {}", pd.id)));
                }
            }
            let fam = Arc::new(RwLock::new(FamilyStore {
                id: dto.id.clone(),
                name: dto.name.clone(),
                description: dto.description.clone(),
                icon: dto.icon.clone(),
                ports: Vec::new(),
                attributes: dto.attributes.iter().cloned().map(AttributeStore::from_full_dto).collect(),
                parent_kit: None,
                event_bus: Weak::new(),
                hash_cache: Cache::default(),
            }));
            let fw = Arc::downgrade(&fam);
            let mut port_refs: Vec<PortStoreRef> = Vec::new();
            for pd in dto.ports.clone() {
                let mut pstore = PortStore::from_full_dto(pd);
                pstore.parent_family = fw.clone();
                port_refs.push(Arc::new(RwLock::new(pstore)));
            }
            if let Ok(mut frw) = fam.write() {
                frw.ports = port_refs;
            }
            g.families.push(fam);
            let kw = Arc::downgrade(kit);
            if let Some(ff) = g.families.last() {
                if let Ok(mut fa) = ff.write() {
                    fa.parent_kit = Some(kw);
                }
            }
            g.invalidate_hash();
            g.invalidate_validation();
            drop(g);
            {
                let g2 = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                for pd in &dto.ports {
                    let Some(pref) = g2.port_by_id(&pd.id) else {
                        return Err(SetError::Internal(format!("port {} missing after family insert", pd.id)));
                    };
                    pref.write().map_err(|_| SetError::LockPoisoned("port".into()))?.set_compatible_ports_from_ids(&pd.compatible_ports, &*g2);
                }
            }
            event_wire::wire_graph_bus(kit);
            Ok(())
        }

        pub fn remove_family_dto(kit: &KitGraphRef, family_id: &str) -> std::result::Result<Option<FamilyFullDto>, SetError> {
            let fid = Id::from(family_id);
            let pos = {
                let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                g.families.iter().position(|f| f.read().map(|r| r.id == fid).unwrap_or(false))
            };
            let Some(pos) = pos else {
                return Ok(None);
            };
            {
                let g = kit.read().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                Self::assert_family_removable(&*g, &fid)?;
            }
            let fam = { kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?.families.remove(pos) };
            let dto = fam.read().map_err(|_| SetError::LockPoisoned("family".into()))?.to_full_dto();
            {
                let g = kit.write().map_err(|_| SetError::LockPoisoned("kit".into()))?;
                g.invalidate_hash();
                g.invalidate_validation();
            }
            Self::purge_dead_port_compatibility(kit);
            event_wire::wire_graph_bus(kit);
            Ok(Some(dto))
        }

        pub(crate) fn ensure_port_unused_by_connectors(kit: &KitGraphRef, pid: &Id) -> std::result::Result<(), SemioError> {
            let g = kit.read().map_err(|_| SemioError::LockPoisoned("kit"))?;
            Self::check_port_unused_by_connectors(&*g, pid).map_err(|e| SemioError::InvalidOperation(e.to_string()))
        }

        pub(crate) fn purge_dead_port_compatibility(kit: &KitGraphRef) {
            let Ok(g) = kit.read() else {
                return;
            };
            for p in &g.ports {
                if let Ok(mut pw) = p.write() {
                    pw.compatible_ports.retain(|w| w.upgrade().is_some());
                }
            }
            for f in &g.families {
                if let Ok(fr) = f.read() {
                    for p in &fr.ports {
                        if let Ok(mut pw) = p.write() {
                            pw.compatible_ports.retain(|w| w.upgrade().is_some());
                        }
                    }
                }
            }
        }

