            let gref: &KitGraphRef = ctx.data()?;
            let g = lock_graph(gref)?;
            let d = self.0.read().map_err(|_| Error::new("design lock poisoned"))?;
            let qid = Id::from(quality_id.as_str());
            Ok(crate::read::design_sum_quality(&*d, &*g, &qid))
