        #[test]
        fn generated_schema_sdl_matches_semio_graphql_schema() {
            let checked_in = std::fs::read_to_string(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("..").join("graphql").join("schema.graphql")).expect("read semio/graphql/schema.graphql");
            let s = kit_graphql::schema_sdl();
            assert!(!s.contains("scalar JSON"), "SDL must not declare generic JSON; use named scalars");
            assert!(!s.contains("JSON!"), "SDL must not use JSON output fields");
            assert_graphql_schema_hygiene(&s);
            assert_eq!(s, checked_in, "run `npx nx build semio/graphql` to regenerate semio/graphql/schema.graphql from semio/rs");
        }

        /// 🧾 Guards for cleaned store/DTO GraphQL surface (see repo cleanup plan).
        fn assert_graphql_schema_hygiene(s: &str) {
            assert!(!s.contains("Gql"), "SDL must not expose ad hoc Gql* names");
            assert!(!s.contains("AuthorShallowRow") && !s.contains("RowObject"), "SDL must not expose legacy *Row graph wrappers");
            assert!(!s.contains("piecePlacement"), "SDL must not expose design-level piecePlacement aggregate");
            assert!(!s.contains("PiecePlacementMetadataDto"), "SDL must not declare PiecePlacementMetadataDto");
            assert!(s.contains("parentPiece:") && s.contains("depth: Int!") && s.contains("path: [PieceStore!]!"), "SDL must expose PieceStore hierarchy fields");
            for bad in ["TypeShallowList", "DesignShallowList", "PieceFullList", "ConnectionFullList"] {
                assert!(!s.contains(bad), "SDL must not declare list scalar {bad}");
            }
            for required in [
                "type KitStore",
                "type DesignStore",
                "type PieceStore",
                "type TypeStore",
                "type ConnectionStore",
                "type ConnectorStore",
                "type RepresentationStore",
                "type ReplaceableCatalogStore",
                "type KitSession",
                "type KitSessionMutation",
                "type KitGraph",
                "type KitAlternative",
                "type KitDraft",
                "type KitTransaction",
            ] {
                assert!(s.contains(required), "SDL must declare {required}");
            }
            assert!(s.contains("session: KitSession!"), "Query.session must exist");
            assert!(!s.contains("kitStore") && !s.contains("KitStoreMutation") && !s.contains("KitReadScope"), "legacy kit batch/read scope surface removed");
            for forbidden_entity in [
                "\ntype Design\n",
                "\ntype Piece\n",
                "\ntype Type\n",
                "\ntype Connection\n",
                "\ntype Connector\n",
                "\ntype Representation\n",
                "\ntype Kit\n",
            ] {
                assert!(!s.contains(forbidden_entity), "SDL must not declare bare/mixed entity {forbidden_entity:?}");
            }
            for wrapper in [
                "KitStoreNode",
                "DesignNode",
                "PieceNode",
                "TypeNode",
                "ConnectionNode",
                "ConnectorNode",
                "RepresentationNode",
                "ReplaceableCatalogNode",
            ] {
                assert!(!s.contains(&format!("type {wrapper} {{")), "SDL must not leak *Node / internal GraphQL wrapper names: {wrapper}");
            }
            assert!(!s.contains("StoreGraphql"), "SDL must not leak internal *StoreGraphql Rust struct suffix into SDL");
            assert!(s.contains("replaceableCatalog(selection: [String!]!): ReplaceableCatalogStore!"), "replaceable catalog resolver");
            assert!(s.contains("types: [TypeStore!]!") && s.contains("designs: [DesignStore!]!"), "ReplaceableCatalog exposes store refs");
            assert!(s.contains("container: KitStore!") && s.contains("container: DesignStore!"), "container back-refs use *Store SDL names");
            assert!(s.contains("metadata: DesignMetadataDto!") && s.contains("shallow: DesignShallowDto!"), "Design DTO tiers");
        }

        #[test]
        #[ignore = "writes the generated SDL to SEMIO_GRAPHQL_SCHEMA_OUT"]
        fn export_semio_graphql_schema_file() {
            let out = std::env::var("SEMIO_GRAPHQL_SCHEMA_OUT").expect("SEMIO_GRAPHQL_SCHEMA_OUT");
            let path = std::path::PathBuf::from(out);
            if let Some(parent) = path.parent() {
                std::fs::create_dir_all(parent).expect("create schema output parent");
            }
            std::fs::write(path, kit_graphql::schema_sdl()).expect("write generated GraphQL schema");
        }

        #[test]
        fn query_session_wip_id_via_schema() {
            let kit: crate::kit_graph::KitGraphRef = Arc::new(RwLock::new(KitGraph::new("gql-name")));
            let expected_id = kit.read().expect("read").id.to_string();
            let (tx, rx) = async_channel::unbounded();
            kit_graphql::spawn_actor(kit.clone(), rx);
            let out = futures_lite::future::block_on(async move {
                let body = r#"{"query":"query { session { id wip { id } } }"}"#;
                let mut req = kit_graphql::request_from_json(body).expect("json");
                req = req.data(kit).data(tx).data(kit_graphql::GraphQlOverride::default());
                let schema = kit_graphql::schema();
                let resp = async_graphql::Response::from(schema.execute(req).await);
                serde_json::to_value(resp).expect("to json")
            });
            let sid = out.pointer("/data/session/id").and_then(|n| n.as_str());
            let wid = out.pointer("/data/session/wip/id").and_then(|n| n.as_str());
            assert_eq!(sid, wid, "session id must match wip graph id: {out:?}");
            assert_eq!(sid, Some(expected_id.as_str()), "wip id must match kit graph id");
        }

