            let cmds = [ChangeKitCommand::Name { name: "b".into() }, ChangeKitCommand::Name { name: "c".into() }];
            let inv = ChangeKitCommand::apply_many(&kit, &cmds).expect("apply_many");
            assert_eq!(kit.read().expect("r").name, "c");
            undo_inverses(&kit, &inv);
